 // Document Import reverse relations (Phase 1)\n  documentImportsCreated        DocumentImport[]            @relation(name: \"DocumentImportCreatedBy\")\n  documentImportsUpdated        DocumentImport[]            @relation(name: \"DocumentImportUpdatedBy\")\n  documentImportsDeleted        DocumentImport[]            @relation(name: \"DocumentImportDeletedBy\")\n  facilityExternalRefsConfirmed FacilityExternalReference[] @relation(name: \"FacilityExternalRefConfirmedBy\")\n  tripInspectionsOverridden     Trip[]                      @relation(name: \"TripInspectionOverriddenBy\")\n  truckDefectsReported          CarrierTruckDefect[]        @relation(name: \"TruckDefectReportedBy\")\n  truckDefectsResolved          CarrierTruckDefect[]        @relation(name: \"TruckDefectResolvedBy\")\n\n  // TKT-0015 Prompt 2b — Wave 4 reverse relations (driver pay + workflow + templates)\n  driverInvitationsCreated           DriverInvitation[]           @relation(name: \"DriverInvitationCreatedBy\")\n  driverInvitationsUpdated           DriverInvitation[]           @relation(name: \"DriverInvitationUpdatedBy\")\n  supportTicketsCreated              SupportTicket[]              @relation(name: \"SupportTicketCreatedBy\")\n  supportTicketsUpdated              SupportTicket[]              @relation(name: \"SupportTicketUpdatedBy\")\n  playbooksCreated                   Playbook[]                   @relation(name: \"PlaybookCreatedBy\")\n  playbooksUpdated                   Playbook[]                   @relation(name: \"PlaybookUpdatedBy\")\n  playbookInstancesCreated           PlaybookInstance[]           @relation(name: \"PlaybookInstanceCreatedBy\")\n  playbookInstancesUpdated           PlaybookInstance[]           @relation(name: \"PlaybookInstanceUpdatedBy\")\n  playbookTriggersCreated            PlaybookTrigger[]            @relation(name: \"PlaybookTriggerCreatedBy\")\n  playbookTriggersUpdated            PlaybookTrigger[]            @relation(name: \"PlaybookTriggerUpdatedBy\")\n  stepTemplatesCreated               StepTemplate[]               @relation(name: \"StepTemplateCreatedBy\")\n  stepTemplatesUpdated               StepTemplate[]               @relation(name: \"StepTemplateUpdatedBy\")\n  routeTemplatesCreated              RouteTemplate[]              @relation(name: \"RouteTemplateCreatedBy\")\n  routeTemplatesUpdated              RouteTemplate[]              @relation(name: \"RouteTemplateUpdatedBy\")\n  routeTemplateStopsCreated          RouteTemplateStop[]          @relation(name: \"RouteTemplateStopCreatedBy\")\n  driverCompensationTemplatesUpdated DriverCompensationTemplate[] @relation(name: \"DriverCompensationTemplateUpdatedBy\")\n  loadDriverAssignmentsUpdated       LoadDriverAssignment[]       @relation(name: \"LoadDriverAssignmentUpdatedBy\")\n  loadPayComponentsUpdated           LoadPayComponent[]           @relation(name: \"LoadPayComponentUpdatedBy\")\n  payComponentAttachmentsUpdated     PayComponentAttachment[]     @relation(name: \"PayComponentAttachmentUpdatedBy\")\n  driverBonusesUpdated               DriverBonus[]                @relation(name: \"DriverBonusUpdatedBy\")\n  driverDeductionsUpdated            DriverDeduction[]            @relation(name: \"DriverDeductionUpdatedBy\")\n  driverSettlementsUpdated           DriverSettlement[]           @relation(name: \"DriverSettlementUpdatedBy\")\n  driverDisputesUpdated              DriverDispute[]              @relation(name: \"DriverDisputeUpdatedBy\")\n\n  @@unique([email, tenantId])\n  @@index([tenantId])\n  @@index([email])\n  @@index([tenantId, role, isActive])\n}\n\nmodel Truck {\n  id               String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId         String    @db.Uuid\n  make             String\n  model            String\n  year             Int\n  vin              String\n  licensePlate     String\n  odometer         Int // Whole miles only (federal requirement)\n  inMaintenance    Boolean   @default(false)\n  documentMetadata Json? // JSONB: registration number, insurance expiry, etc.\n  isDispatchReady  Boolean   @default(false)\n  createdById      String?   @db.Uuid\n  updatedById      String?   @db.Uuid\n  createdAt        DateTime  @default(now()) @db.Timestamptz\n  updatedAt        DateTime  @updatedAt @db.Timestamptz\n  archivedAt       DateTime? @db.Timestamptz\n  isSample         Boolean   @default(false)\n\n  tenant            Tenant             @relation(fields: [tenantId], references: [id])\n  createdBy         User?              @relation(name: \"TruckCreatedBy\", fields: [createdById], references: [id])\n  updatedBy         User?              @relation(name: \"TruckUpdatedBy\", fields: [updatedById], references: [id])\n  assignedRoutes    Route[]\n  documents         Document[]\n  maintenanceEvents MaintenanceEvent[]\n  scheduledServices ScheduledService[]\n  gpsLocations      GPSLocation[]\n  safetyEvents      SafetyEvent[]\n  fuelRecords       FuelRecord[]\n  tagAssignments    TagAssignment[]\n  loads             Load[]\n\n  @@unique([tenantId, vin])\n  @@index([tenantId])\n  @@index([archivedAt])\n}\n\nmodel DriverInvitation {\n  id                      String           @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId                String           @db.Uuid\n  email                   String\n  firstName               String\n  lastName                String\n  licenseNumber           String?\n  licenseNumberCiphertext Bytes?\n  licenseNumberIv         Bytes?\n  licenseNumberTag        Bytes?\n  licenseNumberKeyId      String?\n  licenseNumberLast4      String?          @db.VarChar(8)\n  middleName              String?\n  fullName                String?\n  dateOfBirth             DateTime?        @db.Date\n  dateOfBirthCiphertext   Bytes?\n  dateOfBirthIv           Bytes?\n  dateOfBirthTag          Bytes?\n  dateOfBirthKeyId        String?\n  dateOfBirthLast4        String?          @db.VarChar(8)\n  phoneNumber             String?\n  address                 String?\n  licenseExpirationDate   DateTime?        @db.Date\n  role                    UserRole         @default(DRIVER)\n  permissions             Json?\n  expiresAt               DateTime         @db.Timestamptz\n  status                  InvitationStatus @default(PENDING)\n  acceptedAt              DateTime?        @db.Timestamptz\n  userId                  String?          @db.Uuid\n  createdAt               DateTime         @default(now()) @db.Timestamptz\n  updatedAt               DateTime         @updatedAt @db.Timestamptz\n  createdById             String?          @db.Uuid\n  updatedById             String?          @db.Uuid\n\n  tenant    Tenant @relation(fields: [tenantId], references: [id])\n  createdBy User?  @relation(name: \"DriverInvitationCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User?  @relation(name: \"DriverInvitationUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([email])\n  @@index([tenantId, status])\n}\n\nmodel Route {\n  id             String      @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId       String      @db.Uuid\n  driverId       String      @db.Uuid\n  truckId        String?     @db.Uuid\n  carrierTruckId String?     @db.Uuid\n  origin         String\n  destination    String\n  scheduledDate  DateTime    @db.Timestamptz\n  status         RouteStatus @default(PLANNED)\n  notes          String?\n  name           String?\n  completedAt    DateTime?   @db.Timestamptz\n  version        Int         @default(1)\n  startOdometer  Int?\n  endOdometer    Int?\n  distanceMiles  Float?\n  createdById    String?     @db.Uuid\n  updatedById    String?     @db.Uuid\n  deletedAt      DateTime?   @db.Timestamptz\n  deletedById    String?     @db.Uuid\n  createdAt      DateTime    @default(now()) @db.Timestamptz\n  updatedAt      DateTime    @updatedAt @db.Timestamptz\n  archivedAt     DateTime?   @db.Timestamptz\n\n  tenant            Tenant            @relation(fields: [tenantId], references: [id])\n  driver            User              @relation(fields: [driverId], references: [id])\n  truck             Truck?            @relation(fields: [truckId], references: [id])\n  carrierTruck      CarrierTruck?     @relation(fields: [carrierTruckId], references: [id])\n  createdBy         User?             @relation(name: \"RouteCreatedBy\", fields: [createdById], references: [id])\n  updatedBy         User?             @relation(name: \"RouteUpdatedBy\", fields: [updatedById], references: [id])\n  deletedBy         User?             @relation(name: \"RouteDeletedBy\", fields: [deletedById], references: [id], onDelete: SetNull)\n  documents         Document[]\n  safetyEvents      SafetyEvent[]\n  expenses          RouteExpense[]\n  payments          RoutePayment[]\n  loads             Load[]\n  stops             RouteStop[]\n  coDrivers         RouteDriver[]\n  driverAssignments DriverRouteJoin[]\n\n  @@index([tenantId])\n  @@index([driverId])\n  @@index([truckId])\n  @@index([carrierTruckId])\n  @@index([scheduledDate])\n  @@index([status])\n  @@index([archivedAt])\n  @@index([deletedAt])\n  @@index([tenantId, driverId, scheduledDate])\n}\n\nmodel RouteDriver {\n  id        String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  routeId   String    @db.Uuid\n  driverId  String    @db.Uuid\n  role      String    @default(\"co-driver\")\n  createdAt DateTime  @default(now()) @db.Timestamptz\n  tenantId  String    @db.Uuid\n  updatedAt DateTime? @db.Timestamptz\n  createdBy String?   @db.Uuid\n  updatedBy String?   @db.Uuid\n  deletedAt DateTime? @db.Timestamptz\n  deletedBy String?   @db.Uuid\n\n  route   Route  @relation(fields: [routeId], references: [id], onDelete: Cascade)\n  driver  User   @relation(name: \"RouteCoDrivers\", fields: [driverId], references: [id])\n  tenant  Tenant @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n  creator User?  @relation(name: \"RouteDriverCreatedBy\", fields: [createdBy], references: [id], onDelete: SetNull)\n\n  @@unique([routeId, driverId])\n  @@index([routeId])\n  @@index([driverId])\n  @@index([tenantId])\n  @@index([tenantId, createdAt])\n}\n\nmodel Document {\n  id           String        @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId     String        @db.Uuid\n  truckId      String?       @db.Uuid\n  routeId      String?       @db.Uuid\n  driverId     String?       @db.Uuid\n  loadId       String?       @db.Uuid\n  fileName     String\n  s3Key        String\n  contentType  String\n  sizeBytes    Int\n  uploadedBy   String        @db.Uuid\n  documentType DocumentType?\n  isRestricted Boolean       @default(false) @map(\"is_restricted\")\n  expiryDate   DateTime?     @db.Timestamptz\n  notes        String?\n  description  String?       @db.Text\n  externalUrl  String?\n  createdById  String?       @db.Uuid // NEW (Wave 2)\n  updatedById  String?       @db.Uuid // NEW (Wave 2)\n  createdAt    DateTime      @default(now()) @db.Timestamptz\n  updatedAt    DateTime      @updatedAt @db.Timestamptz\n\n  tenant    Tenant @relation(fields: [tenantId], references: [id])\n  truck     Truck? @relation(fields: [truckId], references: [id])\n  route     Route? @relation(fields: [routeId], references: [id])\n  driver    User?  @relation(name: \"DriverDocuments\", fields: [driverId], references: [id])\n  load      Load?  @relation(fields: [loadId], references: [id])\n  uploader  User   @relation(fields: [uploadedBy], references: [id]) // PRESERVE\n  createdBy User?  @relation(name: \"DocumentCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull) // NEW\n  updatedBy User?  @relation(name: \"DocumentUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull) // NEW\n\n  @@index([tenantId])\n  @@index([truckId])\n  @@index([routeId])\n  @@index([driverId])\n  @@index([loadId])\n  @@index([expiryDate])\n  @@index([uploadedBy])\n  @@index([tenantId, driverId])\n  @@index([tenantId, isRestricted], name: \"document_tenant_restricted_idx\")\n}\n\nmodel MaintenanceEvent {\n  id                String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId          String   @db.Uuid\n  truckId           String   @db.Uuid\n  serviceType       String\n  serviceDate       DateTime @db.Timestamptz\n  odometerAtService Int\n  cost              Decimal? @db.Decimal(10, 2)\n  provider          String?\n  notes             String?\n  createdById       String?  @db.Uuid\n  updatedById       String?  @db.Uuid\n  createdAt         DateTime @default(now()) @db.Timestamptz\n  updatedAt         DateTime @updatedAt @db.Timestamptz\n\n  tenant    Tenant @relation(fields: [tenantId], references: [id])\n  truck     Truck  @relation(fields: [truckId], references: [id])\n  createdBy User?  @relation(name: \"MaintenanceEventCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User?  @relation(name: \"MaintenanceEventUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([truckId])\n  @@index([serviceDate])\n}\n\nmodel ScheduledService {\n  id               String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId         String    @db.Uuid\n  truckId          String    @db.Uuid\n  serviceType      String\n  intervalDays     Int?\n  intervalMiles    Int?\n  baselineDate     DateTime  @db.Timestamptz\n  baselineOdometer Int\n  notes            String?\n  isCompleted      Boolean   @default(false)\n  completedAt      DateTime? @db.Timestamptz\n  createdById      String?   @db.Uuid\n  updatedById      String?   @db.Uuid\n  createdAt        DateTime  @default(now()) @db.Timestamptz\n  updatedAt        DateTime  @updatedAt @db.Timestamptz\n\n  tenant    Tenant @relation(fields: [tenantId], references: [id])\n  truck     Truck  @relation(fields: [truckId], references: [id])\n  createdBy User?  @relation(name: \"ScheduledServiceCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User?  @relation(name: \"ScheduledServiceUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([truckId])\n  @@index([isCompleted])\n}\n\nmodel NotificationLog {\n  id               String             @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId         String             @db.Uuid\n  idempotencyKey   String             @unique\n  notificationType String\n  entityType       String?\n  entityId         String?            @db.Uuid\n  recipientEmail   String\n  status           NotificationStatus @default(PENDING)\n  sentAt           DateTime?          @db.Timestamptz\n  failedAt         DateTime?          @db.Timestamptz\n  errorMessage     String?\n  retryCount       Int                @default(0)\n  emailSubject     String?\n  externalId       String?\n  createdAt        DateTime           @default(now()) @db.Timestamptz\n  updatedAt        DateTime           @updatedAt @db.Timestamptz\n\n  tenant Tenant @relation(fields: [tenantId], references: [id])\n\n  @@index([tenantId])\n  @@index([status])\n  @@index([idempotencyKey])\n  @@index([createdAt])\n}\n\nmodel GPSLocation {\n  id             String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId       String   @db.Uuid\n  truckId        String?  @db.Uuid\n  carrierTruckId String?  @db.Uuid\n  latitude       Decimal  @db.Decimal(10, 8)\n  longitude      Decimal  @db.Decimal(11, 8)\n  speed          Int?\n  heading        Int?\n  altitude       Int?\n  accuracy       Decimal? @db.Decimal(6, 2)\n  timestamp      DateTime @db.Timestamptz\n  createdAt      DateTime @default(now()) @db.Timestamptz\n\n  tenant       Tenant        @relation(fields: [tenantId], references: [id])\n  truck        Truck?        @relation(fields: [truckId], references: [id])\n  carrierTruck CarrierTruck? @relation(fields: [carrierTruckId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId])\n  @@index([truckId])\n  @@index([timestamp])\n  @@index([tenantId, timestamp])\n  @@index([carrierTruckId])\n  @@index([carrierTruckId, timestamp])\n}\n\nmodel SafetyEvent {\n  id         String              @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId   String              @db.Uuid\n  truckId    String              @db.Uuid\n  driverId   String?             @db.Uuid\n  routeId    String?             @db.Uuid\n  eventType  SafetyEventType\n  severity   SafetyEventSeverity\n  gForce     Decimal?            @db.Decimal(4, 2)\n  speed      Int?\n  speedLimit Int?\n  latitude   Decimal             @db.Decimal(10, 8)\n  longitude  Decimal             @db.Decimal(11, 8)\n  timestamp  DateTime            @db.Timestamptz\n  metadata   Json?\n  createdAt  DateTime            @default(now()) @db.Timestamptz\n\n  tenant Tenant @relation(fields: [tenantId], references: [id])\n  truck  Truck  @relation(fields: [truckId], references: [id])\n  driver User?  @relation(fields: [driverId], references: [id])\n  route  Route? @relation(fields: [routeId], references: [id])\n\n  @@index([tenantId])\n  @@index([truckId])\n  @@index([driverId])\n  @@index([routeId])\n  @@index([eventType])\n  @@index([severity])\n  @@index([timestamp])\n  @@index([tenantId, timestamp])\n}\n\nmodel FuelRecord {\n  id          String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId    String   @db.Uuid\n  truckId     String   @db.Uuid\n  fuelType    FuelType\n  quantity    Decimal  @db.Decimal(10, 2)\n  unitCost    Decimal? @db.Decimal(10, 4)\n  totalCost   Decimal? @db.Decimal(10, 2)\n  odometer    Int\n  location    String?\n  latitude    Decimal? @db.Decimal(10, 8)\n  longitude   Decimal? @db.Decimal(11, 8)\n  timestamp   DateTime @db.Timestamptz\n  isEstimated Boolean  @default(false)\n  notes       String?\n  createdById String?  @db.Uuid\n  createdAt   DateTime @default(now()) @db.Timestamptz\n\n  tenant    Tenant @relation(fields: [tenantId], references: [id])\n  truck     Truck  @relation(fields: [truckId], references: [id])\n  createdBy User?  @relation(name: \"FuelRecordCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([truckId])\n  @@index([timestamp])\n  @@index([tenantId, timestamp])\n  @@index([isEstimated])\n}\n\nmodel Tag {\n  id          String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId    String   @db.Uuid\n  name        String\n  color       String   @default(\"#3b82f6\")\n  createdById String?  @db.Uuid\n  updatedById String?  @db.Uuid\n  createdAt   DateTime @default(now()) @db.Timestamptz\n  updatedAt   DateTime @updatedAt @db.Timestamptz\n\n  tenant      Tenant          @relation(fields: [tenantId], references: [id])\n  createdBy   User?           @relation(name: \"TagCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy   User?           @relation(name: \"TagUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n  assignments TagAssignment[]\n\n  @@unique([tenantId, name])\n  @@index([tenantId])\n}\n\nmodel TagAssignment {\n  id        String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId  String   @db.Uuid\n  tagId     String   @db.Uuid\n  truckId   String?  @db.Uuid\n  userId    String?  @db.Uuid\n  createdAt DateTime @default(now()) @db.Timestamptz\n\n  tenant Tenant @relation(fields: [tenantId], references: [id])\n  tag    Tag    @relation(fields: [tagId], references: [id], onDelete: Cascade)\n  truck  Truck? @relation(fields: [truckId], references: [id], onDelete: Cascade)\n  user   User?  @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([tagId, truckId])\n  @@unique([tagId, userId])\n  @@index([tenantId])\n  @@index([tagId])\n  @@index([truckId])\n  @@index([userId])\n}\n\nmodel ExpenseCategory {\n  id              String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId        String   @db.Uuid\n  name            String\n  isSystemDefault Boolean  @default(false)\n  createdById     String?  @db.Uuid\n  updatedById     String?  @db.Uuid\n  createdAt       DateTime @default(now()) @db.Timestamptz\n  updatedAt       DateTime @updatedAt @db.Timestamptz\n\n  tenant        Tenant                @relation(fields: [tenantId], references: [id])\n  createdBy     User?                 @relation(name: \"ExpenseCategoryCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy     User?                 @relation(name: \"ExpenseCategoryUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n  expenses      RouteExpense[]\n  templateItems ExpenseTemplateItem[]\n\n  @@unique([tenantId, name])\n  @@index([tenantId])\n}\n\nmodel RouteExpense {\n  id          String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId    String    @db.Uuid\n  routeId     String    @db.Uuid\n  categoryId  String    @db.Uuid\n  amount      Decimal   @db.Decimal(10, 2)\n  description String\n  notes       String?\n  deletedAt   DateTime? @db.Timestamptz\n  createdById String?   @db.Uuid\n  updatedById String?   @db.Uuid\n  createdAt   DateTime  @default(now()) @db.Timestamptz\n  updatedAt   DateTime  @updatedAt @db.Timestamptz\n\n  tenant    Tenant          @relation(fields: [tenantId], references: [id])\n  route     Route           @relation(fields: [routeId], references: [id])\n  category  ExpenseCategory @relation(fields: [categoryId], references: [id])\n  createdBy User?           @relation(name: \"RouteExpenseCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User?           @relation(name: \"RouteExpenseUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([routeId])\n  @@index([categoryId])\n  @@index([deletedAt])\n}\n\nmodel ExpenseTemplate {\n  id          String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId    String   @db.Uuid\n  name        String\n  createdById String?  @db.Uuid\n  updatedById String?  @db.Uuid\n  createdAt   DateTime @default(now()) @db.Timestamptz\n  updatedAt   DateTime @updatedAt @db.Timestamptz\n\n  tenant    Tenant                @relation(fields: [tenantId], references: [id])\n  items     ExpenseTemplateItem[]\n  createdBy User?                 @relation(name: \"ExpenseTemplateCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User?                 @relation(name: \"ExpenseTemplateUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@unique([tenantId, name])\n  @@index([tenantId])\n}\n\nmodel ExpenseTemplateItem {\n  id          String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  templateId  String  @db.Uuid\n  categoryId  String  @db.Uuid\n  tenantId    String  @db.Uuid\n  amount      Decimal @db.Decimal(10, 2)\n  description String\n\n  template ExpenseTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  category ExpenseCategory @relation(fields: [categoryId], references: [id])\n  tenant   Tenant          @relation(fields: [tenantId], references: [id])\n\n  @@index([templateId])\n  @@index([categoryId])\n  @@index([tenantId])\n}\n\nmodel RoutePayment {\n  id          String        @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId    String        @db.Uuid\n  routeId     String        @db.Uuid\n  amount      Decimal       @db.Decimal(10, 2)\n  status      PaymentStatus @default(PENDING)\n  paidAt      DateTime?     @db.Timestamptz\n  notes       String?\n  deletedAt   DateTime?     @db.Timestamptz\n  createdById String?       @db.Uuid\n  updatedById String?       @db.Uuid\n  createdAt   DateTime      @default(now()) @db.Timestamptz\n  updatedAt   DateTime      @updatedAt @db.Timestamptz\n\n  tenant    Tenant @relation(fields: [tenantId], references: [id])\n  route     Route  @relation(fields: [routeId], references: [id])\n  createdBy User?  @relation(name: \"RoutePaymentCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User?  @relation(name: \"RoutePaymentUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([routeId])\n  @@index([status])\n  @@index([deletedAt])\n}\n\n// ─── CRM Models ─────────────────────────────────────────────\n\nenum CustomerPriority {\n  LOW\n  MEDIUM\n  HIGH\n  VIP\n}\n\nenum CustomerStatus {\n  ACTIVE\n  INACTIVE\n  PROSPECT\n}\n\nenum InteractionType {\n  EMAIL\n  PHONE\n  MEETING\n  NOTE\n  LOAD_UPDATE\n  ETA_NOTIFICATION\n}\n\nmodel Customer {\n  id                 String           @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId           String           @db.Uuid\n  companyName        String\n  contactName        String?\n  email              String?\n  phone              String?\n  address            String?\n  city               String?\n  state              String?\n  zipCode            String?\n  priority           CustomerPriority @default(MEDIUM)\n  status             CustomerStatus   @default(ACTIVE)\n  notes              String?\n  emailNotifications Boolean          @default(true)\n  totalLoads         Int              @default(0)\n  totalRevenue       Decimal          @default(0) @db.Decimal(12, 2)\n  lastLoadDate       DateTime?        @db.Timestamptz\n  createdById        String?          @db.Uuid\n  updatedById        String?          @db.Uuid\n  createdAt          DateTime         @default(now()) @db.Timestamptz\n  updatedAt          DateTime         @updatedAt @db.Timestamptz\n  isSample           Boolean          @default(false)\n\n  tenant       Tenant                @relation(fields: [tenantId], references: [id])\n  interactions CustomerInteraction[]\n  loads        Load[]\n  createdBy    User?                 @relation(name: \"CustomerCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy    User?                 @relation(name: \"CustomerUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@unique([tenantId, companyName])\n  @@index([tenantId])\n  @@index([priority])\n  @@index([status])\n}\n\nmodel CustomerInteraction {\n  id          String          @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId    String          @db.Uuid\n  customerId  String          @db.Uuid\n  type        InteractionType\n  subject     String\n  description String?\n  isAutomated Boolean         @default(false)\n  createdBy   String?         @db.Uuid\n  createdById String?         @db.Uuid\n  updatedById String?         @db.Uuid\n  createdAt   DateTime        @default(now()) @db.Timestamptz\n\n  tenant        Tenant   @relation(fields: [tenantId], references: [id])\n  customer      Customer @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  createdByUser User?    @relation(name: \"CustomerInteractionCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedByUser User?    @relation(name: \"CustomerInteractionUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([customerId])\n  @@index([type])\n  @@index([createdAt])\n}\n\n// ─── Invoice & Billing Models ───────────────────────────────\n\nenum SysAdminInvoiceStatus {\n  DRAFT\n  SENT\n  PAID\n  OVERDUE\n  VOID\n}\n\nenum InvoiceStatus {\n  DRAFT\n  SENT\n  PAID\n  OVERDUE\n  CANCELLED\n}\n\nenum InvoiceItemType {\n  LINEHAUL\n  FUEL_SURCHARGE\n  DETENTION\n  STOP_OFF\n  LAYOVER\n  TONU\n  LUMPER\n  ACCESSORIAL\n  TAX\n  OTHER\n}\n\nenum InvoiceItemUnit {\n  FLAT\n  PER_MILE\n  PER_CWT\n  PER_PIECE\n  PER_HOUR\n  PERCENT\n}\n\nmodel Invoice {\n  id            String        @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId      String        @db.Uuid\n  customerId    String?       @db.Uuid\n  routeId       String?       @db.Uuid\n  loadId        String?       @db.Uuid\n  invoiceNumber String\n  amount        Decimal       @db.Decimal(12, 2)\n  tax           Decimal       @default(0) @db.Decimal(10, 2)\n  totalAmount   Decimal       @db.Decimal(12, 2)\n  status        InvoiceStatus @default(DRAFT)\n  issueDate     DateTime      @db.Timestamptz\n  dueDate       DateTime      @db.Timestamptz\n  paidDate      DateTime?     @db.Timestamptz\n  notes         String?\n  bolNumber     String?\n  proNumber     String?\n  poNumber      String?\n  commodity     String?\n  weightLbs     Int?\n  pieces        Int?\n  loadedMiles   Decimal?      @db.Decimal(10, 2)\n  createdById   String?       @db.Uuid\n  updatedById   String?       @db.Uuid\n  createdAt     DateTime      @default(now()) @db.Timestamptz\n  updatedAt     DateTime      @updatedAt @db.Timestamptz\n  archivedAt    DateTime?     @db.Timestamptz\n\n  tenant    Tenant        @relation(fields: [tenantId], references: [id])\n  createdBy User?         @relation(name: \"InvoiceCreatedBy\", fields: [createdById], references: [id])\n  updatedBy User?         @relation(name: \"InvoiceUpdatedBy\", fields: [updatedById], references: [id])\n  load      Load?         @relation(fields: [loadId], references: [id])\n  items     InvoiceItem[]\n\n  @@unique([tenantId, invoiceNumber])\n  @@index([tenantId])\n  @@index([status])\n  @@index([dueDate])\n  @@index([loadId])\n  @@index([archivedAt])\n  @@index([tenantId, status])\n}\n\nmodel InvoiceItem {\n  id          String          @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  invoiceId   String          @db.Uuid\n  tenantId    String          @db.Uuid\n  description String\n  itemType    InvoiceItemType @default(OTHER)\n  unitType    InvoiceItemUnit @default(FLAT)\n  quantity    Decimal         @db.Decimal(10, 2)\n  unitPrice   Decimal         @db.Decimal(10, 2)\n  amount      Decimal         @db.Decimal(12, 2)\n  createdById String?         @db.Uuid\n  updatedById String?         @db.Uuid\n  createdAt   DateTime        @default(now()) @db.Timestamptz\n  updatedAt   DateTime        @updatedAt @db.Timestamptz\n\n  invoice   Invoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  tenant    Tenant  @relation(fields: [tenantId], references: [id])\n  createdBy User?   @relation(name: \"InvoiceItemCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User?   @relation(name: \"InvoiceItemUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([invoiceId])\n  @@index([tenantId])\n}\n\n// ─── SysAdmin Invoice Models ────────────────────────────────\n\nmodel SysAdminInvoice {\n  id                 String                @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId           String                @db.Uuid\n  invoiceNumber      String                @unique\n  status             SysAdminInvoiceStatus @default(DRAFT)\n  issueDate          DateTime              @db.Timestamptz\n  dueDate            DateTime              @db.Timestamptz\n  billingPeriodStart DateTime?             @db.Timestamptz\n  billingPeriodEnd   DateTime?             @db.Timestamptz\n  isRecurring        Boolean               @default(false)\n  subtotal           Decimal               @db.Decimal(12, 2)\n  total              Decimal               @db.Decimal(12, 2)\n  notes              String?\n  paidAt             DateTime?             @db.Timestamptz\n  archivedAt         DateTime?             @db.Timestamptz\n  createdById        String?               @db.Uuid\n  updatedById        String?               @db.Uuid\n  createdAt          DateTime              @default(now()) @db.Timestamptz\n  updatedAt          DateTime              @updatedAt @db.Timestamptz\n\n  tenant    Tenant                @relation(fields: [tenantId], references: [id])\n  items     SysAdminInvoiceItem[]\n  createdBy User?                 @relation(name: \"SysAdminInvoiceCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User?                 @relation(name: \"SysAdminInvoiceUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([status])\n  @@index([dueDate])\n  @@index([archivedAt])\n}\n\nmodel SysAdminInvoiceItem {\n  id          String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  invoiceId   String    @db.Uuid\n  chargeType  String?\n  description String\n  quantity    Decimal   @db.Decimal(10, 2)\n  unitPrice   Decimal   @db.Decimal(10, 2)\n  amount      Decimal   @db.Decimal(12, 2)\n  tenantId    String    @db.Uuid\n  createdAt   DateTime? @default(now()) @db.Timestamptz\n  updatedAt   DateTime? @updatedAt @db.Timestamptz\n  createdBy   String?   @db.Uuid\n  updatedBy   String?   @db.Uuid\n  deletedAt   DateTime? @db.Timestamptz\n  deletedBy   String?   @db.Uuid\n\n  invoice SysAdminInvoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  tenant  Tenant          @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n  creator User?           @relation(name: \"SysAdminInvoiceItemCreatedBy\", fields: [createdBy], references: [id], onDelete: SetNull)\n  updater User?           @relation(name: \"SysAdminInvoiceItemUpdatedBy\", fields: [updatedBy], references: [id], onDelete: SetNull)\n\n  @@index([invoiceId])\n  @@index([tenantId])\n}\n\n// ─── Payroll Models ─────────────────────────────────────────\n\nenum PayrollStatus {\n  DRAFT\n  APPROVED\n  PAID\n}\n\nenum LoadStatus {\n  PENDING\n  DISPATCHED\n  PICKED_UP\n  IN_TRANSIT\n  DELIVERED\n  INVOICED\n  CANCELLED\n}\n\nmodel PayrollRecord {\n  id             String        @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId       String        @db.Uuid\n  driverId       String        @db.Uuid\n  periodStart    DateTime      @db.Timestamptz\n  periodEnd      DateTime      @db.Timestamptz\n  basePay        Decimal       @db.Decimal(10, 2)\n  bonuses        Decimal       @default(0) @db.Decimal(10, 2)\n  deductions     Decimal       @default(0) @db.Decimal(10, 2)\n  totalPay       Decimal       @db.Decimal(10, 2)\n  milesLogged    Int           @default(0)\n  loadsCompleted Int           @default(0)\n  status         PayrollStatus @default(DRAFT)\n  paidAt         DateTime?     @db.Timestamptz\n  notes          String?\n  createdById    String?       @db.Uuid\n  updatedById    String?       @db.Uuid\n  createdAt      DateTime      @default(now()) @db.Timestamptz\n  updatedAt      DateTime      @updatedAt @db.Timestamptz\n  archivedAt     DateTime?     @db.Timestamptz\n\n  tenant    Tenant @relation(fields: [tenantId], references: [id])\n  driver    User   @relation(fields: [driverId], references: [id])\n  createdBy User?  @relation(name: \"PayrollCreatedBy\", fields: [createdById], references: [id])\n  updatedBy User?  @relation(name: \"PayrollUpdatedBy\", fields: [updatedById], references: [id])\n\n  @@index([tenantId])\n  @@index([driverId])\n  @@index([status])\n  @@index([periodStart])\n  @@index([archivedAt])\n}\n\n// ─── Load / Dispatch Models ──────────────────────────────────\n\nmodel Load {\n  id             String     @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId       String     @db.Uuid\n  loadNumber     String\n  customerId     String     @db.Uuid\n  routeId        String?    @db.Uuid\n  sequence       Int?\n  driverId       String?    @db.Uuid\n  truckId        String?    @db.Uuid\n  origin         String\n  destination    String\n  pickupDate     DateTime   @db.Timestamptz\n  deliveryDate   DateTime?  @db.Timestamptz\n  weight         Int?\n  commodity      String?\n  rate           Decimal    @db.Decimal(12, 2)\n  status         LoadStatus @default(PENDING)\n  notes          String?\n  pickupLat      Decimal?   @db.Decimal(10, 8) // Geocoded from origin address\n  pickupLng      Decimal?   @db.Decimal(11, 8)\n  deliveryLat    Decimal?   @db.Decimal(10, 8) // Geocoded from destination address\n  deliveryLng    Decimal?   @db.Decimal(11, 8)\n  geofenceFlags  Json? // JSONB: tracks which alerts have fired\n  // shape: { pickupAlerted: boolean, deliveryAlerted: boolean }\n  trackingToken  String?    @unique // Public token for customer shipment tracking\n  createdById    String?    @db.Uuid\n  updatedById    String?    @db.Uuid\n  createdAt      DateTime   @default(now()) @db.Timestamptz\n  updatedAt      DateTime   @updatedAt @db.Timestamptz\n  archivedAt     DateTime?  @db.Timestamptz\n  pickupStopId   String?    @db.Uuid // FK → RouteStop (set when load is assigned to a route)\n  deliveryStopId String?    @db.Uuid // FK → RouteStop\n  isSample       Boolean    @default(false)\n\n  tenant       Tenant      @relation(fields: [tenantId], references: [id])\n  customer     Customer    @relation(fields: [customerId], references: [id])\n  route        Route?      @relation(fields: [routeId], references: [id])\n  driver       User?       @relation(name: \"DriverLoads\", fields: [driverId], references: [id])\n  truck        Truck?      @relation(fields: [truckId], references: [id])\n  createdBy    User?       @relation(name: \"LoadCreatedBy\", fields: [createdById], references: [id])\n  updatedBy    User?       @relation(name: \"LoadUpdatedBy\", fields: [updatedById], references: [id])\n  invoices     Invoice[]\n  documents    Document[]\n  routeStops   RouteStop[] @relation(name: \"RouteStopLoad\")\n  pickupStop   RouteStop?  @relation(name: \"LoadPickupStop\", fields: [pickupStopId], references: [id])\n  deliveryStop RouteStop?  @relation(name: \"LoadDeliveryStop\", fields: [deliveryStopId], references: [id])\n\n  @@unique([tenantId, loadNumber])\n  @@index([tenantId])\n  @@index([customerId])\n  @@index([driverId])\n  @@index([truckId])\n  @@index([status])\n  @@index([pickupDate])\n  @@index([trackingToken])\n  @@index([archivedAt])\n  @@index([routeId, sequence])\n  @@index([tenantId, status, archivedAt])\n}\n\n// ─── Integration Models ──────────────────────────────────────\n\nmodel TenantIntegration {\n  id          String              @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId    String              @db.Uuid\n  provider    IntegrationProvider\n  category    IntegrationCategory\n  enabled     Boolean             @default(false)\n  configJson  Json? // JSONB: future API keys, webhook URLs, etc.\n  createdById String?             @db.Uuid\n  updatedById String?             @db.Uuid\n  createdAt   DateTime            @default(now()) @db.Timestamptz\n  updatedAt   DateTime            @updatedAt @db.Timestamptz\n\n  tenant    Tenant @relation(fields: [tenantId], references: [id])\n  createdBy User?  @relation(name: \"TenantIntegrationCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User?  @relation(name: \"TenantIntegrationUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@unique([tenantId, provider])\n  @@index([tenantId])\n}\n\n// ─── Support Ticket Models ───────────────────────────────────\n\nenum SupportTicketStatus {\n  OPEN\n  IN_PROGRESS\n  WAITING_ON_CUSTOMER\n  RESOLVED\n  CLOSED\n}\n\nenum SupportTicketCategory {\n  BILLING\n  BUG\n  FEATURE\n  GENERAL\n}\n\nenum SupportTicketPriority {\n  LOW\n  NORMAL\n  HIGH\n  URGENT\n}\n\nenum TicketMessageSenderType {\n  OWNER\n  ADMIN\n}\n\nmodel SupportTicket {\n  id            String                @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  ticketNumber  String                @unique\n  tenantId      String?               @db.Uuid\n  submittedBy   String                @db.Uuid\n  fromPage      String\n  category      SupportTicketCategory @default(GENERAL)\n  priority      SupportTicketPriority @default(NORMAL)\n  title         String\n  description   String\n  platform      String?\n  attachmentUrl String?\n  attachmentKey String?\n  screenshotKey String?\n  status        SupportTicketStatus   @default(OPEN)\n  resolution    String?\n  resolvedAt    DateTime?             @db.Timestamptz\n  createdAt     DateTime              @default(now()) @db.Timestamptz\n  updatedAt     DateTime              @updatedAt @db.Timestamptz\n  createdById   String?               @db.Uuid\n  updatedById   String?               @db.Uuid\n\n  createdBy User? @relation(name: \"SupportTicketCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User? @relation(name: \"SupportTicketUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([submittedBy])\n  @@index([status])\n  @@index([createdAt])\n}\n\nmodel TicketMessage {\n  id          String                  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  ticketId    String                  @db.Uuid\n  senderType  TicketMessageSenderType\n  senderLabel String\n  body        String\n  createdAt   DateTime                @default(now()) @db.Timestamptz\n\n  @@index([ticketId])\n  @@index([createdAt])\n}\n\n// ─── Multi-Stop Route Models ─────────────────────────────────\n\nmodel RouteStop {\n  id           String          @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  routeId      String          @db.Uuid\n  tenantId     String          @db.Uuid\n  loadId       String?         @db.Uuid // Links stop to the load it serves (nullable: fuel/weigh stops have no load)\n  position     Int // 1-based ordering\n  type         RouteStopType\n  address      String\n  lat          Decimal?        @db.Decimal(10, 8)\n  lng          Decimal?        @db.Decimal(11, 8)\n  scheduledAt  DateTime?       @db.Timestamptz\n  arrivedAt    DateTime?       @db.Timestamptz\n  departedAt   DateTime?       @db.Timestamptz\n  notes        String?\n  contactName  String? // Shipper/receiver contact at this stop\n  contactPhone String?\n  bolNumber    String? // Bill of Lading number for this stop's load\n  poNumber     String? // Customer PO number\n  status       RouteStopStatus @default(PENDING)\n  geofenceHit  Boolean         @default(false)\n  createdById  String?         @db.Uuid\n  updatedById  String?         @db.Uuid\n  createdAt    DateTime        @default(now()) @db.Timestamptz\n  updatedAt    DateTime        @updatedAt @db.Timestamptz\n\n  route            Route  @relation(fields: [routeId], references: [id], onDelete: Cascade)\n  tenant           Tenant @relation(fields: [tenantId], references: [id])\n  load             Load?  @relation(name: \"RouteStopLoad\", fields: [loadId], references: [id])\n  pickupForLoads   Load[] @relation(name: \"LoadPickupStop\")\n  deliveryForLoads Load[] @relation(name: \"LoadDeliveryStop\")\n  createdBy        User?  @relation(name: \"RouteStopCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy        User?  @relation(name: \"RouteStopUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([routeId])\n  @@index([tenantId])\n  @@index([loadId])\n  @@index([routeId, position])\n  @@index([status])\n}\n\n// ─── Driver Route Join Models ────────────────────────────────\n\nenum DriverPaymentMethod {\n  FIXED_AMOUNT\n  HOURLY\n  PER_MILE\n}\n\nmodel DriverRouteJoin {\n  id            String              @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId      String              @db.Uuid\n  routeId       String              @db.Uuid\n  driverId      String              @db.Uuid\n  isMainDriver  Boolean             @default(false)\n  paymentMethod DriverPaymentMethod\n  fixedAmount   Decimal?            @db.Decimal(10, 2)\n  hourlyRate    Decimal?            @db.Decimal(10, 2)\n  numberOfHours Decimal?            @db.Decimal(10, 2)\n  perMileRate   Decimal?            @db.Decimal(10, 4)\n  numberOfMiles Decimal?            @db.Decimal(10, 2)\n  createdAt     DateTime            @default(now()) @db.Timestamptz\n  updatedAt     DateTime            @updatedAt @db.Timestamptz\n\n  tenant Tenant @relation(fields: [tenantId], references: [id])\n  route  Route  @relation(fields: [routeId], references: [id], onDelete: Cascade)\n  driver User   @relation(name: \"DriverRouteJoins\", fields: [driverId], references: [id])\n\n  @@unique([routeId, driverId])\n  @@index([tenantId])\n  @@index([routeId])\n  @@index([driverId])\n}\n\n// ─── Fleet Messaging Models ──────────────────────────────────\n\nmodel FleetMessage {\n  id          String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId    String    @db.Uuid\n  routeId     String?   @db.Uuid\n  loadId      String?   @db.Uuid\n  dispatchId  String?   @db.Uuid\n  senderId    String    @db.Uuid\n  senderRole  String\n  body        String\n  recipientId String?   @db.Uuid\n  isBroadcast Boolean   @default(false)\n  readAt      DateTime? @db.Timestamptz\n  createdById String?   @db.Uuid // NEW (Wave 2 — createdById ONLY, no updatedById)\n  createdAt   DateTime  @default(now()) @db.Timestamptz\n\n  stopId   String? @map(\"stop_id\") @db.Uuid\n  audioUrl String? @map(\"audio_url\")\n\n  dispatch  Trip?        @relation(fields: [dispatchId], references: [id], onDelete: SetNull)\n  stop      CarrierStop? @relation(fields: [stopId], references: [id], onDelete: SetNull)\n  createdBy User?        @relation(name: \"FleetMessageCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull) // NEW\n\n  @@index([tenantId])\n  @@index([routeId])\n  @@index([loadId])\n  @@index([dispatchId])\n  @@index([stopId])\n  @@index([recipientId])\n  @@index([createdAt])\n  @@index([senderId])\n  @@index([tenantId, createdAt])\n}\n\n// ─── Push Token Models ───────────────────────────────────────\n\nmodel PushToken {\n  id        String    @id @default(cuid())\n  userId    String    @db.Uuid\n  token     String\n  platform  String // 'ios' | 'android'\n  updatedAt DateTime  @updatedAt @db.Timestamptz\n  createdAt DateTime  @default(now()) @db.Timestamptz\n  tenantId  String    @db.Uuid\n  createdBy String?   @db.Uuid\n  updatedBy String?   @db.Uuid\n  deletedAt DateTime? @db.Timestamptz\n  deletedBy String?   @db.Uuid\n\n  user    User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  tenant  Tenant @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n  creator User?  @relation(name: \"PushTokenCreatedBy\", fields: [createdBy], references: [id], onDelete: SetNull)\n\n  @@unique([userId, platform]) // one token per user per platform\n  @@index([userId])\n  @@index([tenantId])\n}\n\n// ─── HOS and Incident Models ──────────────────────────────────\n\nenum HOSDutyStatus {\n  OFF_DUTY\n  SLEEPER_BERTH\n  DRIVING\n  ON_DUTY\n}\n\nenum IncidentCategory {\n  ACCIDENT\n  VIOLATION\n  MECHANICAL\n  HAZARD\n  OTHER\n}\n\nenum IncidentSeverity {\n  LOW\n  MEDIUM\n  HIGH\n}\n\n// Workflow Engine Enums\nenum PlaybookEntityType {\n  DRIVER\n  VEHICLE\n  PARTNER\n  DISPATCH\n  OTHER\n}\n\nenum PlaybookCategory {\n  ONBOARDING\n  SAFETY\n  OPERATIONS\n  COMPLIANCE\n  PARTNER\n  CUSTOM\n  VEHICLE_INSPECTION\n}\n\nenum InstanceStatus {\n  NOT_STARTED\n  IN_PROGRESS\n  COMPLETED\n  BLOCKED\n}\n\nenum StepStatus {\n  NOT_STARTED\n  IN_PROGRESS\n  COMPLETE\n  FAILED\n  SKIPPED\n}\n\nenum NotifType {\n  STEP_ASSIGNED\n  STEP_OVERDUE\n  INSTANCE_BLOCKED\n  DISPATCH_READY\n  STEP_FAILED\n  APPROVAL_NEEDED\n  DAILY_DIGEST\n}\n\nenum OverdueRecipient {\n  DRIVER\n  OWNER\n  BOTH\n}\n\nenum NotifChannel {\n  PUSH\n  SMS\n  IN_APP\n  EMAIL\n}\n\nenum PhaseType {\n  PRE_START\n  DAY_1\n  WEEK_1\n  ONGOING\n  NONE\n}\n\nenum StepType {\n  DOCUMENT_UPLOAD\n  FORM_FILL\n  INSPECTION_ITEM\n  SIGNATURE\n  TRAINING_ACK\n  APPROVAL\n  THIRD_PARTY\n  CUSTOM_NOTE\n}\n\nenum AssigneeRole {\n  DRIVER\n  DISPATCHER\n  MECHANIC\n  SAFETY_MANAGER\n  THIRD_PARTY\n}\n\nenum TriggerEvent {\n  ON_DRIVER_CREATE\n  ON_VEHICLE_CREATE\n  ON_DISPATCH_CREATE\n  ON_DISPATCH_DEPART\n  ON_DISPATCH_DELIVER\n  ON_PARTNER_CREATE\n  MANUAL_ONLY\n  RECURRING\n}\n\n// ─── Phase 47 Enums ───────────────────────────────────────────────────────────\n\nenum FleetSizeBucket {\n  OWNER_OPERATOR\n  SMALL\n  MEDIUM\n  LARGE\n}\n\nenum TenantStatus {\n  TRIAL\n  ACTIVE\n  PAST_DUE\n  SUSPENDED\n  CANCELLED\n}\n\nenum ProvisioningPhase {\n  MINIMAL\n  HYDRATED\n}\n\nenum SubscriptionStatus {\n  TRIALING\n  ACTIVE\n  PAST_DUE\n  CANCELLED\n  SUSPENDED\n}\n\nenum AutomationScope {\n  SYSTEM\n  TENANT\n}\n\nenum AutomationRunStatus {\n  FIRED\n  SKIPPED_CONDITION\n  SKIPPED_ALREADY_RAN\n  FAILED\n  PENDING\n  SENT\n}\n\n// ─── Driver Pay Enums ─────────────────────────────────────────────────────────\n\nenum EmploymentType {\n  W2_EMPLOYEE\n  OWNER_OPERATOR_1099\n  LEASE_OPERATOR\n}\n\nenum DriverPayType {\n  CPM\n  HOURLY\n  FLAT_PER_LOAD\n  PERCENTAGE\n  DAILY\n  SALARY\n}\n\nenum RateUnit {\n  PER_MILE\n  PER_HOUR\n  PER_LOAD\n  PERCENTAGE\n  PER_DAY\n  ANNUAL\n}\n\nenum DriverRole {\n  MAIN_DRIVER\n  CO_DRIVER\n}\n\nenum MileageSource {\n  PCMILER\n  GOOGLE\n  ELD\n  MANUAL\n  RAND_MCNALLY\n}\n\nenum DriverAssignmentStatus {\n  DRAFT\n  PENDING_REVIEW\n  APPROVED\n  PAID\n  DISPUTED\n  CORRECTED\n}\n\nenum PayComponentType {\n  BASE_PAY_MILEAGE\n  BASE_PAY_HOURLY\n  BASE_PAY_FLAT\n  BASE_PAY_PERCENTAGE\n  BASE_PAY_DAILY\n  FUEL_SURCHARGE\n  OVERTIME\n  HAZMAT_PREMIUM\n  HOLIDAY_PREMIUM\n  LOAD_COMPLETION_BONUS\n  FUEL_EFFICIENCY_BONUS\n  DETENTION\n  LAYOVER\n  TONU\n  STOP_OFF\n  TARP\n  BREAKDOWN\n  PER_DIEM\n  LUMPER_REIMBURSEMENT\n  SCALE_REIMBURSEMENT\n  FUEL_REIMBURSEMENT\n  ADVANCE_REPAYMENT\n  ESCROW_CONTRIBUTION\n  FUEL_CARD_DEBT\n  CARGO_CLAIM\n  EQUIPMENT_DAMAGE\n  GARNISHMENT\n  CHILD_SUPPORT\n  ADJUSTMENT_POSITIVE\n  ADJUSTMENT_NEGATIVE\n}\n\nenum PayComponentCategory {\n  EARNING\n  BONUS\n  ACCESSORIAL\n  ALLOWANCE\n  REIMBURSEMENT\n  DEDUCTION\n  ADJUSTMENT\n}\n\nenum PayComponentUnit {\n  MILES\n  HOURS\n  STOPS\n  DAYS\n  FLAT\n  PERCENTAGE\n}\n\nenum BonusType {\n  SIGN_ON\n  RETENTION\n  SAFETY\n  FUEL_EFFICIENCY\n  REFERRAL\n  PERFORMANCE\n  OTHER\n}\n\nenum DeductionType {\n  ADVANCE\n  ESCROW\n  GARNISHMENT\n  CHILD_SUPPORT\n  EQUIPMENT_LEASE\n  INSURANCE\n  OTHER\n}\n\nenum DeductionSchedule {\n  ONE_TIME\n  EVERY_SETTLEMENT\n  FIXED_INSTALLMENTS\n}\n\nenum DriverSettlementStatus {\n  DRAFT\n  FINALIZED\n  PAID\n  VOIDED\n}\n\nenum DisputeTargetType {\n  LOAD_PAY\n  SETTLEMENT\n  COMPONENT\n}\n\nenum DisputeIssueCategory {\n  WRONG_AMOUNT\n  MISSING_PAY\n  WRONG_MILES\n  MISSING_RECEIPT\n  OTHER\n}\n\nenum DisputeStatus {\n  OPEN\n  IN_REVIEW\n  RESOLVED_PAID\n  RESOLVED_NO_CHANGE\n  CLOSED\n}\n\nmodel DriverHOSEntry {\n  id          String        @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId    String        @db.Uuid\n  driverId    String        @db.Uuid\n  status      HOSDutyStatus\n  startTime   DateTime      @db.Timestamptz\n  endTime     DateTime?     @db.Timestamptz\n  notes       String?\n  createdById String?       @db.Uuid\n  updatedById String?       @db.Uuid\n  createdAt   DateTime      @default(now()) @db.Timestamptz\n  updatedAt   DateTime      @updatedAt @db.Timestamptz\n\n  tenant    Tenant @relation(fields: [tenantId], references: [id])\n  driver    User   @relation(name: \"DriverHOSEntries\", fields: [driverId], references: [id])\n  createdBy User?  @relation(name: \"DriverHOSEntryCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User?  @relation(name: \"DriverHOSEntryUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([driverId])\n  @@index([driverId, startTime])\n  @@index([tenantId, driverId, startTime])\n}\n\nmodel DriverIncident {\n  id          String           @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId    String           @db.Uuid\n  driverId    String           @db.Uuid\n  category    IncidentCategory\n  severity    IncidentSeverity\n  description String\n  latitude    Decimal?         @db.Decimal(10, 8)\n  longitude   Decimal?         @db.Decimal(11, 8)\n  photoS3Key  String?\n  reportedAt  DateTime         @db.Timestamptz\n  notes       String?\n  createdById String?          @db.Uuid\n  updatedById String?          @db.Uuid\n  createdAt   DateTime         @default(now()) @db.Timestamptz\n  updatedAt   DateTime         @updatedAt @db.Timestamptz\n\n  tenant    Tenant @relation(fields: [tenantId], references: [id])\n  driver    User   @relation(name: \"DriverIncidents\", fields: [driverId], references: [id])\n  createdBy User?  @relation(name: \"DriverIncidentCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User?  @relation(name: \"DriverIncidentUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([driverId])\n  @@index([tenantId, reportedAt])\n  @@index([category])\n  @@index([severity])\n}\n\n// ─── Carrier Operations Models ───────────────────────────────────────────────\n// All carrier models use orgId (maps to org_id in SQL) for tenant scoping.\n// Model names are prefixed to avoid conflicts with existing models\n// (Load, Document, Truck already exist in this schema).\n\nmodel CarrierClient {\n  id             String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId          String    @map(\"org_id\") @db.Uuid\n  name           String\n  dbaName        String?   @map(\"dba_name\")\n  mcNumber       String?   @map(\"mc_number\")\n  dotNumber      String?   @map(\"dot_number\")\n  taxId          String?   @map(\"tax_id\")\n  primaryContact String?   @map(\"primary_contact\")\n  email          String?\n  phone          String?\n  website        String?\n  addressLine1   String?   @map(\"address_line1\")\n  addressLine2   String?   @map(\"address_line2\")\n  city           String?\n  state          String?\n  zip            String?\n  country        String    @default(\"US\")\n  status         String    @default(\"active\")\n  isSample       Boolean   @default(false) @map(\"is_sample\")\n  portalAccess   Boolean   @default(false) @map(\"portal_access\")\n  portalEmail    String?   @map(\"portal_email\")\n  paymentTerms   Int       @default(30) @map(\"payment_terms\")\n  creditLimit    Decimal?  @map(\"credit_limit\") @db.Decimal(12, 2)\n  notes          String?\n  createdById    String?   @map(\"created_by_id\") @db.Uuid // NEW (Wave 2)\n  updatedById    String?   @map(\"updated_by_id\") @db.Uuid // NEW (Wave 2)\n  deletedAt      DateTime? @map(\"deleted_at\") @db.Timestamptz\n  deletedById    String?   @map(\"deleted_by_id\") @db.Uuid\n  createdAt      DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt      DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  tenant           Tenant                 @relation(fields: [orgId], references: [id])\n  createdBy        User?                  @relation(name: \"CarrierClientCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull) // NEW\n  updatedBy        User?                  @relation(name: \"CarrierClientUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull) // NEW\n  deletedBy        User?                  @relation(name: \"CarrierClientDeletedBy\", fields: [deletedById], references: [id], onDelete: SetNull)\n  contracts        CarrierContract[]\n  routeTemplates   RouteTemplate[]\n  stops            CarrierStop[]\n  carrierDocuments CarrierDocument[]\n  expenses         CarrierExpense[]\n  driverPayRecords DriverPayRecord[]\n  carrierLoads     CarrierLoad[]\n  contacts         CarrierClientContact[]\n\n  // Document Import (Phase 1)\n  documentImports    DocumentImport[]\n  externalReferences FacilityExternalReference[]\n  documentProfiles   DocumentProfile[]\n\n  @@index([orgId])\n  @@index([status])\n  @@index([deletedAt])\n  @@map(\"clients\")\n}\n\nmodel CarrierClientContact {\n  id        String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId     String   @map(\"org_id\") @db.Uuid\n  clientId  String   @map(\"client_id\") @db.Uuid\n  name      String\n  role      String?\n  phone     String?\n  email     String?\n  isMain    Boolean  @default(false) @map(\"is_main\")\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  tenant Tenant        @relation(fields: [orgId], references: [id])\n  client CarrierClient @relation(fields: [clientId], references: [id], onDelete: Cascade)\n\n  @@index([orgId])\n  @@index([clientId])\n  @@map(\"client_contacts\")\n}\n\nmodel CarrierContract {\n  id                     String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId                  String    @map(\"org_id\") @db.Uuid\n  clientId               String    @map(\"client_id\") @db.Uuid\n  contractNumber         String    @unique @map(\"contract_number\")\n  contractName           String?   @map(\"contract_name\")\n  contractType           String    @default(\"spot\") @map(\"contract_type\")\n  effectiveDate          DateTime? @map(\"effective_date\") @db.Date\n  expirationDate         DateTime? @map(\"expiration_date\") @db.Date\n  rateType               String    @default(\"per_mile\") @map(\"rate_type\")\n  baseRate               Decimal?  @map(\"base_rate\") @db.Decimal(10, 4)\n  fuelSurchargeMethod    String    @default(\"none\") @map(\"fuel_surcharge_method\")\n  fuelSurchargeRate      Decimal?  @map(\"fuel_surcharge_rate\") @db.Decimal(6, 4)\n  detentionFreeMinutes   Int       @default(120) @map(\"detention_free_minutes\")\n  detentionRatePerHour   Decimal?  @map(\"detention_rate_per_hour\") @db.Decimal(10, 2)\n  tonuRate               Decimal?  @map(\"tonu_rate\") @db.Decimal(10, 2)\n  layoverRatePerDay      Decimal?  @map(\"layover_rate_per_day\") @db.Decimal(10, 2)\n  paymentTermsOverride   String?   @map(\"payment_terms_override\")\n  autoRenew              Boolean   @default(false) @map(\"auto_renew\")\n  status                 String    @default(\"active\")\n  notes                  String?\n  // Driver Pay additions (Phase 1)\n  defaultFreeTimeMinutes Int?      @map(\"default_free_time_minutes\")\n  createdById            String?   @map(\"created_by_id\") @db.Uuid // NEW (Wave 2)\n  updatedById            String?   @map(\"updated_by_id\") @db.Uuid // NEW (Wave 2)\n  deletedAt              DateTime? @map(\"deleted_at\") @db.Timestamptz\n  deletedById            String?   @map(\"deleted_by_id\") @db.Uuid\n  createdAt              DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt              DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  tenant         Tenant            @relation(fields: [orgId], references: [id])\n  createdBy      User?             @relation(name: \"CarrierContractCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull) // NEW\n  updatedBy      User?             @relation(name: \"CarrierContractUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull) // NEW\n  deletedBy      User?             @relation(name: \"CarrierContractDeletedBy\", fields: [deletedById], references: [id], onDelete: SetNull)\n  client         CarrierClient     @relation(fields: [clientId], references: [id])\n  routeTemplates RouteTemplate[]\n  carrierLoads   CarrierLoad[]\n  documents      CarrierDocument[]\n\n  // Document Import (Phase 1)\n  documentImports          DocumentImport[]\n  pinnedByDocumentProfiles DocumentProfile[] @relation(name: \"DocumentProfilePinnedContract\")\n\n  @@index([clientId])\n  @@index([status])\n  @@index([orgId])\n  @@index([deletedAt])\n  @@map(\"contracts\")\n}\n\nmodel CarrierFacility {\n  id                  String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId               String    @map(\"org_id\") @db.Uuid\n  name                String\n  // Allowed values: 'terminal' | 'yard' | 'warehouse' | 'drop_yard' | 'customer_site' | 'driver_residence'\n  // Not a Prisma enum — enforcement lives in the SQL CHECK constraint\n  // `facilities_facility_type_check`. Widened to admit 'driver_residence' by\n  // migration 20260802173535_widen_facility_type_check. Any new value must be\n  // added to that constraint in a migration or the write fails at the database.\n  facilityType        String    @default(\"terminal\") @map(\"facility_type\")\n  addressLine1        String?   @map(\"address_line1\")\n  addressLine2        String?   @map(\"address_line2\")\n  city                String?\n  state               String?\n  zip                 String?\n  country             String    @default(\"US\")\n  latitude            Float?\n  longitude           Float?\n  contactName         String?   @map(\"contact_name\")\n  contactPhone        String?   @map(\"contact_phone\")\n  contactEmail        String?   @map(\"contact_email\")\n  lumperRequired      Boolean   @default(false) @map(\"lumper_required\")\n  appointmentRequired Boolean   @default(false) @map(\"appointment_required\")\n  contacts            Json      @default(\"[]\")\n  notes               String?\n  // ─── Document Import (Phase 1, spec Sections 6 + 9) ───────────────────────\n  // A driver residence is visible only to that driver, the owner, and dispatchers\n  // with explicit permission — enforced server-side, never as a UI hide (Section 9).\n  isDriverResidence   Boolean   @default(false) @map(\"is_driver_residence\")\n  residentDriverId    String?   @map(\"resident_driver_id\") @db.Uuid\n  createdById         String?   @map(\"created_by_id\") @db.Uuid // NEW (Wave 2)\n  updatedById         String?   @map(\"updated_by_id\") @db.Uuid // NEW (Wave 2)\n  // Soft delete (quick-530). Before this column existed, `softDeleteFacility`\n  // wrote `inactive_<type>` into `facilityType` — a value\n  // `facilities_facility_type_check` has never admitted, so the write was a\n  // 23514 every time and soft delete never worked. Stamping this column leaves\n  // `facilityType` alone and constraint-legal.\n  //\n  // Read rule, and it cuts both ways: FILTER A PICKER, HYDRATE A TRIP'S OWN\n  // STOPS. Pickers, candidate sets and write-time ownership checks all take\n  // `deletedAt: null`. Queries that fetch facilities BY ID for stops already on\n  // a trip or load must NOT filter — dropping the row blanks the facility name\n  // on a live itinerary, the same failure the driver-residence mask exists to\n  // avoid.\n  deletedAt           DateTime? @map(\"deleted_at\") @db.Timestamptz\n  // Added by quick-534. The migration that created `deleted_at` withheld this\n  // one on purpose — \"add it with the code that needs it\" — and Recently\n  // Deleted is that code: it selects a `deletedBy` relation for every\n  // soft-deletable entity, so without this facilities could be deleted but\n  // never listed or restored.\n  //\n  // The relation below carries `onDelete: SetNull` to match the siblings\n  // exactly, but there is NO foreign key in the database on `deleted_by_id` —\n  // not here and not on any of the seven siblings, verified with\n  // `pg_get_constraintdef`. `created_by_id`/`updated_by_id` DO have one. That\n  // Prisma-vs-DB gap is the pre-existing house pattern; do not \"fix\" it here in\n  // isolation.\n  deletedById         String?   @map(\"deleted_by_id\") @db.Uuid\n  createdAt           DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt           DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  tenant             Tenant              @relation(fields: [orgId], references: [id])\n  createdBy          User?               @relation(name: \"CarrierFacilityCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull) // NEW\n  updatedBy          User?               @relation(name: \"CarrierFacilityUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull) // NEW\n  deletedBy          User?               @relation(name: \"CarrierFacilityDeletedBy\", fields: [deletedById], references: [id], onDelete: SetNull)\n  residentDriver     CarrierDriver?      @relation(name: \"FacilityResidentDriver\", fields: [residentDriverId], references: [id], onDelete: SetNull)\n  carrierDrivers     CarrierDriver[]\n  routeTemplateStops RouteTemplateStop[]\n  stops              CarrierStop[]\n\n  externalReferences FacilityExternalReference[]\n  homeBaseForTenants Tenant[]                    @relation(name: \"TenantHomeBase\")\n\n  @@index([orgId])\n  @@index([facilityType])\n  @@index([orgId, isDriverResidence])\n  @@map(\"facilities\")\n}\n\nmodel CarrierDriver {\n  id                  String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId               String    @map(\"org_id\") @db.Uuid\n  userId              String?   @unique @map(\"user_id\") @db.Uuid\n  firstName           String    @map(\"first_name\")\n  lastName            String    @map(\"last_name\")\n  email               String?\n  phone               String?\n  cdlNumber           String?   @map(\"cdl_number\")\n  cdlNumberCiphertext Bytes?    @map(\"cdl_number_ciphertext\")\n  cdlNumberIv         Bytes?    @map(\"cdl_number_iv\")\n  cdlNumberTag        Bytes?    @map(\"cdl_number_tag\")\n  cdlNumberKeyId      String?   @map(\"cdl_number_key_id\")\n  cdlNumberLast4      String?   @map(\"cdl_number_last4\") @db.VarChar(4)\n  cdlState            String?   @map(\"cdl_state\")\n  cdlClass            String?   @map(\"cdl_class\")\n  cdlExpiry           DateTime? @map(\"cdl_expiry\") @db.Date\n  homeTerminalId      String?   @map(\"home_terminal_id\") @db.Uuid\n  payModel            String    @default(\"per_mile\") @map(\"pay_model\")\n  payRate             Decimal?  @map(\"pay_rate\") @db.Decimal(10, 4)\n  payPeriod           String    @default(\"weekly\") @map(\"pay_period\")\n  status              String    @default(\"active\")\n  isSample            Boolean   @default(false) @map(\"is_sample\")\n  notes               String?\n  createdById         String?   @map(\"created_by_id\") @db.Uuid // NEW (Wave 2)\n  updatedById         String?   @map(\"updated_by_id\") @db.Uuid // NEW (Wave 2)\n  deletedAt           DateTime? @map(\"deleted_at\") @db.Timestamptz\n  deletedById         String?   @map(\"deleted_by_id\") @db.Uuid\n  createdAt           DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt           DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  tenant                Tenant            @relation(fields: [orgId], references: [id])\n  createdBy             User?             @relation(name: \"CarrierDriverCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull) // NEW\n  updatedBy             User?             @relation(name: \"CarrierDriverUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull) // NEW\n  deletedBy             User?             @relation(name: \"CarrierDriverDeletedBy\", fields: [deletedById], references: [id], onDelete: SetNull)\n  user                  User?             @relation(name: \"CarrierDriverUser\", fields: [userId], references: [id])\n  homeTerminal          CarrierFacility?  @relation(fields: [homeTerminalId], references: [id])\n  primaryDispatches     Trip[]            @relation(name: \"PrimaryDriver\")\n  coDispatches          Trip[]            @relation(name: \"CoDriver\")\n  expenses              CarrierExpense[]\n  driverPayRecords      DriverPayRecord[]\n  defaultRouteTemplates RouteTemplate[]   @relation(name: \"DefaultDriver\")\n\n  // Driver Pay reverse relations\n  compensationTemplates DriverCompensationTemplate[]\n  loadAssignments       LoadDriverAssignment[]\n  driverBonuses         DriverBonus[]\n  referredBonuses       DriverBonus[]                @relation(\"BonusReferredDriver\")\n  driverDeductions      DriverDeduction[]\n  driverSettlements     DriverSettlement[]\n  driverDisputes        DriverDispute[]\n\n  // Document Import (Phase 1) — driver residence facility, spec Section 9\n  residenceFacilities CarrierFacility[] @relation(name: \"FacilityResidentDriver\")\n\n  @@index([orgId])\n  @@index([status])\n  @@index([deletedAt])\n  @@map(\"carrier_drivers\")\n}\n\nmodel CarrierTruck {\n  id                   String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId                String    @map(\"org_id\") @db.Uuid\n  vehicleId            String    @unique @map(\"vehicle_id\") @db.VarChar(50)\n  displayName          String?   @map(\"display_name\") @db.VarChar(200)\n  unitNumber           String    @map(\"unit_number\")\n  year                 Int?\n  make                 String?\n  model                String?\n  vin                  String?\n  truckType            String    @default(\"semi\") @map(\"truck_type\")\n  payloadCapacityLbs   Int?      @map(\"payload_capacity_lbs\")\n  grossWeightLbs       Int?      @map(\"gross_weight_lbs\")\n  licensePlate         String?   @map(\"license_plate\")\n  licenseState         String?   @map(\"license_state\")\n  licenseExpiry        DateTime? @map(\"license_expiry\") @db.Date\n  registrationExpiry   DateTime? @map(\"registration_expiry\") @db.Date\n  insuranceExpiry      DateTime? @map(\"insurance_expiry\") @db.Date\n  currentOdometerMiles Int?      @map(\"current_odometer_miles\")\n  lastOdometerDate     DateTime? @map(\"last_odometer_date\") @db.Date\n  status               String    @default(\"active\")\n  isSample             Boolean   @default(false) @map(\"is_sample\")\n  notes                String?\n  photoS3Key           String?   @map(\"photo_s3_key\")\n  createdById          String?   @map(\"created_by_id\") @db.Uuid // NEW (Wave 2)\n  updatedById          String?   @map(\"updated_by_id\") @db.Uuid // NEW (Wave 2)\n  deletedAt            DateTime? @map(\"deleted_at\") @db.Timestamptz\n  deletedById          String?   @map(\"deleted_by_id\") @db.Uuid\n  createdAt            DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt            DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  tenant                Tenant               @relation(fields: [orgId], references: [id])\n  createdBy             User?                @relation(name: \"CarrierTruckCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull) // NEW\n  updatedBy             User?                @relation(name: \"CarrierTruckUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull) // NEW\n  deletedBy             User?                @relation(name: \"CarrierTruckDeletedBy\", fields: [deletedById], references: [id], onDelete: SetNull)\n  primaryDispatches     Trip[]               @relation(name: \"PrimaryTruck\")\n  trailerDispatches     Trip[]               @relation(name: \"TrailerTruck\")\n  defects               CarrierTruckDefect[]\n  defaultRouteTemplates RouteTemplate[]      @relation(name: \"DefaultTruck\")\n  gpsLocations          GPSLocation[]\n  routes                Route[]\n\n  @@index([orgId])\n  @@index([status])\n  @@index([deletedAt])\n  @@map(\"carrier_trucks\")\n}\n\n/// Phase 9 (spec Section 12) — a defect raised against a truck by a failed\n/// pre-trip inspection item. `CarrierTruck` had no defect or maintenance\n/// relation before this: `MaintenanceEvent` / `ScheduledService` hang off the\n/// LEGACY `Truck` model, and the only truck-level signal was\n/// `carrier_trucks.status`, which is the wrong instrument — flipping it to\n/// 'maintenance' over a cracked mudflap takes a truck out of service.\n///\n/// Scoped by `orgId`, like every carrier sibling, so it MUST appear in\n/// EXEMPT_MODELS in `lib/db/extensions/tenant-rls.ts`. It does, in this commit.\nmodel CarrierTruckDefect {\n  id               String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId            String    @map(\"org_id\") @db.Uuid\n  truckId          String    @map(\"truck_id\") @db.Uuid\n  dispatchId       String?   @map(\"dispatch_id\") @db.Uuid\n  /// The failed StepInstance that raised it. Uniquely indexed (partial, NOT NULL\n  /// only) so re-submitting the same item UPDATES its defect instead of adding a\n  /// second one. No FK — StepInstance belongs to the workflow module, and a\n  /// cascade across a module boundary is how a truck's defect history quietly\n  /// disappears when someone tidies up an old playbook instance.\n  stepInstanceId   String?   @map(\"step_instance_id\") @db.Uuid\n  itemName         String    @map(\"item_name\")\n  note             String?\n  photoKeys        Json      @default(\"[]\") @map(\"photo_keys\")\n  isCritical       Boolean   @default(false) @map(\"is_critical\")\n  /// 'open' | 'resolved' — enforced live by carrier_truck_defects_status_check.\n  status           String    @default(\"open\")\n  reportedByUserId String?   @map(\"reported_by_user_id\") @db.Uuid\n  reportedAt       DateTime  @default(now()) @map(\"reported_at\") @db.Timestamptz\n  resolvedByUserId String?   @map(\"resolved_by_user_id\") @db.Uuid\n  resolvedAt       DateTime? @map(\"resolved_at\") @db.Timestamptz\n  resolutionNote   String?   @map(\"resolution_note\")\n  createdAt        DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt        DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  tenant     Tenant       @relation(fields: [orgId], references: [id], onDelete: Cascade)\n  truck      CarrierTruck @relation(fields: [truckId], references: [id], onDelete: Cascade)\n  dispatch   Trip?        @relation(fields: [dispatchId], references: [id], onDelete: SetNull)\n  reportedBy User?        @relation(name: \"TruckDefectReportedBy\", fields: [reportedByUserId], references: [id], onDelete: SetNull)\n  resolvedBy User?        @relation(name: \"TruckDefectResolvedBy\", fields: [resolvedByUserId], references: [id], onDelete: SetNull)\n\n  @@index([orgId, truckId, status])\n  @@index([dispatchId])\n  @@map(\"carrier_truck_defects\")\n}\n\nmodel RouteTemplate {\n  id                     String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId                  String    @map(\"org_id\") @db.Uuid\n  templateName           String    @map(\"template_name\")\n  clientId               String    @map(\"client_id\") @db.Uuid\n  contractId             String?   @map(\"contract_id\") @db.Uuid\n  scheduleType           String    @map(\"schedule_type\")\n  recurrenceRule         String?   @map(\"recurrence_rule\")\n  recurrenceTimezone     String    @default(\"America/Chicago\") @map(\"recurrence_timezone\")\n  scheduledDepartureTime String?   @map(\"scheduled_departure_time\")\n  equipmentType          String    @map(\"equipment_type\")\n  tempMinF               Int?      @map(\"temp_min_f\")\n  tempMaxF               Int?      @map(\"temp_max_f\")\n  maxWeightLbs           Int?      @map(\"max_weight_lbs\")\n  commodityDescription   String?   @map(\"commodity_description\")\n  estimatedMiles         Int?      @map(\"estimated_miles\")\n  defaultDriverId        String?   @map(\"default_driver_id\") @db.Uuid\n  defaultTruckId         String?   @map(\"default_truck_id\") @db.Uuid\n  autoGenerateDaysAhead  Int       @default(7) @map(\"auto_generate_days_ahead\")\n  active                 Boolean   @default(true)\n  notes                  String?\n  // ─── Document Import (Phase 1, spec Sections 6 + 8 + 9) ───────────────────\n  // Overrides the tenant default; per-trip choice still wins over this.\n  endStopPolicy          String?   @map(\"end_stop_policy\")\n  /// Where the truck parks when this route's policy is `DESIGNATED_PARKING`, and\n  /// read ONLY under that policy — every other policy computes its own facility,\n  /// so the save path clears this column whenever the policy is written to\n  /// anything else rather than leaving a value nothing will ever read.\n  ///\n  /// A scalar with **no Prisma relation, deliberately**: the FK\n  /// `route_templates_end_stop_facility_id_fkey → facilities(id) ON DELETE SET NULL`\n  /// exists in the database (read off production, not inferred), and declaring the\n  /// relation here would force a back-relation on `CarrierFacility` for no benefit\n  /// — nothing ever navigates from a facility to the templates that park there.\n  endStopFacilityId      String?   @map(\"end_stop_facility_id\") @db.Uuid\n  /// Set when a template was auto-created from a committed import. Such templates\n  /// land in \"Suggested templates\" until a human confirms (spec Section 8).\n  sourceImportId         String?   @map(\"source_import_id\") @db.Uuid\n  isSuggested            Boolean   @default(false) @map(\"is_suggested\")\n  lastAppliedAt          DateTime? @map(\"last_applied_at\") @db.Timestamptz\n  applicationCount       Int       @default(0) @map(\"application_count\")\n  createdAt              DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt              DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz\n  createdById            String?   @map(\"created_by_id\") @db.Uuid\n  updatedById            String?   @map(\"updated_by_id\") @db.Uuid\n\n  tenant        Tenant              @relation(fields: [orgId], references: [id])\n  client        CarrierClient       @relation(fields: [clientId], references: [id])\n  contract      CarrierContract?    @relation(fields: [contractId], references: [id])\n  defaultDriver CarrierDriver?      @relation(name: \"DefaultDriver\", fields: [defaultDriverId], references: [id])\n  defaultTruck  CarrierTruck?       @relation(name: \"DefaultTruck\", fields: [defaultTruckId], references: [id])\n  stops         RouteTemplateStop[]\n  dispatches    Trip[]\n  createdBy     User?               @relation(name: \"RouteTemplateCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy     User?               @relation(name: \"RouteTemplateUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n  sourceImport  DocumentImport?     @relation(name: \"RouteTemplateSourceImport\", fields: [sourceImportId], references: [id], onDelete: SetNull)\n\n  matchedImports DocumentImport[]\n\n  @@index([clientId])\n  @@index([contractId])\n  @@index([active])\n  @@index([orgId])\n  @@index([orgId, isSuggested])\n  @@map(\"route_templates\")\n}\n\nmodel RouteTemplateStop {\n  id                       String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  routeTemplateId          String   @map(\"route_template_id\") @db.Uuid\n  sequenceOrder            Int      @map(\"sequence_order\")\n  stopType                 String   @map(\"stop_type\")\n  facilityId               String   @map(\"facility_id\") @db.Uuid\n  contactName              String?  @map(\"contact_name\")\n  contactPhone             String?  @map(\"contact_phone\")\n  apptWindowStartOffsetMin Int?     @map(\"appt_window_start_offset_min\")\n  apptWindowEndOffsetMin   Int?     @map(\"appt_window_end_offset_min\")\n  expectedDwellMinutes     Int?     @map(\"expected_dwell_minutes\")\n  commodityDescription     String?  @map(\"commodity_description\")\n  bolRequired              Boolean  @default(true) @map(\"bol_required\")\n  podRequired              Boolean  @default(true) @map(\"pod_required\")\n  specialInstructions      String?  @map(\"special_instructions\")\n  createdAt                DateTime @default(now()) @map(\"created_at\") @db.Timestamptz\n  createdById              String?  @map(\"created_by_id\") @db.Uuid\n\n  routeTemplate RouteTemplate   @relation(fields: [routeTemplateId], references: [id], onDelete: Cascade)\n  facility      CarrierFacility @relation(fields: [facilityId], references: [id])\n  createdBy     User?           @relation(name: \"RouteTemplateStopCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n\n  @@unique([routeTemplateId, sequenceOrder])\n  @@index([routeTemplateId])\n  @@map(\"route_template_stops\")\n}\n\nmodel Trip {\n  id                         String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId                      String    @map(\"org_id\") @db.Uuid\n  routeTemplateId            String?   @map(\"route_template_id\") @db.Uuid\n  primaryDriverId            String    @map(\"primary_driver_id\") @db.Uuid\n  coDriverId                 String?   @map(\"co_driver_id\") @db.Uuid\n  truckId                    String    @map(\"truck_id\") @db.Uuid\n  trailerId                  String?   @map(\"trailer_id\") @db.Uuid\n  dispatcherId               String?   @map(\"dispatcher_id\") @db.Uuid\n  scheduledDeparture         DateTime  @map(\"scheduled_departure\") @db.Timestamptz\n  actualDeparture            DateTime? @map(\"actual_departure\") @db.Timestamptz\n  scheduledArrival           DateTime? @map(\"scheduled_arrival\") @db.Timestamptz\n  actualArrival              DateTime? @map(\"actual_arrival\") @db.Timestamptz\n  status                     String    @default(\"planned\")\n  // relay_handoff_stop_id is a plain UUID — NO FK (intentional: avoids circular reference dispatches→stops→dispatches)\n  relayHandoffStopId         String?   @map(\"relay_handoff_stop_id\") @db.Uuid\n  plannedMiles               Decimal?  @map(\"planned_miles\") @db.Decimal(10, 2)\n  actualMiles                Decimal?  @map(\"actual_miles\") @db.Decimal(10, 2)\n  hosCycle                   String    @default(\"us_70\") @map(\"hos_cycle\")\n  notes                      String?\n  // ─── Document Import (Phase 1, spec Sections 6 + 9 + 12) ──────────────────\n  sourceImportId             String?   @map(\"source_import_id\") @db.Uuid\n  endStopPolicy              String?   @map(\"end_stop_policy\")\n  /// Null means \"fall back to the tenant setting\"; a value is a per-trip override.\n  inspectionRequired         Boolean?  @map(\"inspection_required\")\n  inspectionOverriddenById   String?   @map(\"inspection_overridden_by_id\") @db.Uuid\n  inspectionOverriddenReason String?   @map(\"inspection_overridden_reason\")\n  inspectionOverriddenAt     DateTime? @map(\"inspection_overridden_at\") @db.Timestamptz\n  createdById                String?   @map(\"created_by_id\") @db.Uuid // NEW (Wave 2)\n  updatedById                String?   @map(\"updated_by_id\") @db.Uuid // NEW (Wave 2)\n  deletedAt                  DateTime? @map(\"deleted_at\") @db.Timestamptz\n  deletedById                String?   @map(\"deleted_by_id\") @db.Uuid\n  createdAt                  DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt                  DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  tenant                 Tenant               @relation(fields: [orgId], references: [id])\n  createdBy              User?                @relation(name: \"TripCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy              User?                @relation(name: \"TripUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n  deletedBy              User?                @relation(name: \"TripDeletedBy\", fields: [deletedById], references: [id], onDelete: SetNull)\n  routeTemplate          RouteTemplate?       @relation(fields: [routeTemplateId], references: [id])\n  primaryDriver          CarrierDriver        @relation(name: \"PrimaryDriver\", fields: [primaryDriverId], references: [id])\n  coDriver               CarrierDriver?       @relation(name: \"CoDriver\", fields: [coDriverId], references: [id])\n  truck                  CarrierTruck         @relation(name: \"PrimaryTruck\", fields: [truckId], references: [id])\n  trailer                CarrierTruck?        @relation(name: \"TrailerTruck\", fields: [trailerId], references: [id])\n  dispatcher             User?                @relation(name: \"TripDispatcher\", fields: [dispatcherId], references: [id])\n  sourceImport           DocumentImport?      @relation(name: \"TripSourceImport\", fields: [sourceImportId], references: [id], onDelete: SetNull)\n  inspectionOverriddenBy User?                @relation(name: \"TripInspectionOverriddenBy\", fields: [inspectionOverriddenById], references: [id], onDelete: SetNull)\n  stops                  CarrierStop[]\n  carrierLoads           CarrierLoad[]\n  expenses               CarrierExpense[]\n  driverPayRecords       DriverPayRecord[]\n  messages               FleetMessage[]\n  documents              CarrierDocument[]\n  truckDefects           CarrierTruckDefect[]\n\n  @@index([primaryDriverId])\n  @@index([truckId])\n  @@index([status])\n  @@index([scheduledDeparture])\n  @@index([orgId])\n  @@index([deletedAt])\n  @@map(\"dispatches\")\n}\n\nmodel CarrierLoad {\n  id                   String         @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId                String         @map(\"org_id\") @db.Uuid\n  dispatchId           String?        @map(\"dispatch_id\") @db.Uuid\n  contractId           String?        @map(\"contract_id\") @db.Uuid\n  clientId             String         @map(\"client_id\") @db.Uuid\n  loadType             String         @default(\"ftl\") @map(\"load_type\")\n  referenceNumber      String?        @map(\"reference_number\")\n  bolNumber            String?        @map(\"bol_number\")\n  proNumber            String?        @map(\"pro_number\")\n  poNumber             String?        @map(\"po_number\")\n  commodityDescription String?        @map(\"commodity_description\")\n  commodityWeightLbs   Decimal?       @map(\"commodity_weight_lbs\") @db.Decimal(10, 2)\n  commodityPieces      Int?           @map(\"commodity_pieces\")\n  commodityPallets     Int?           @map(\"commodity_pallets\")\n  hazmat               Boolean        @default(false)\n  hazmatClass          String?        @map(\"hazmat_class\")\n  rateType             String         @default(\"flat\") @map(\"rate_type\")\n  rateAmount           Decimal?       @map(\"rate_amount\") @db.Decimal(12, 2)\n  currency             String         @default(\"USD\")\n  brokerFlag           Boolean        @default(false) @map(\"broker_flag\")\n  carrierCost          Decimal?       @map(\"carrier_cost\") @db.Decimal(12, 2)\n  fuelSurcharge        Decimal?       @map(\"fuel_surcharge\") @db.Decimal(12, 2)\n  detentionAmount      Decimal?       @map(\"detention_amount\") @db.Decimal(12, 2)\n  otherCharges         Decimal?       @map(\"other_charges\") @db.Decimal(12, 2)\n  totalRevenue         Decimal?       @map(\"total_revenue\") @db.Decimal(12, 2)\n  status               String         @default(\"pending\")\n  isSample             Boolean        @default(false) @map(\"is_sample\")\n  specialInstructions  String?        @map(\"special_instructions\")\n  notes                String?\n  pendingStopsJson     String?        @map(\"pending_stops_json\") @db.Text\n  // Driver Pay additions (Phase 1)\n  totalMiles           Decimal?       @map(\"total_miles\") @db.Decimal(10, 2)\n  loadedMiles          Decimal?       @map(\"loaded_miles\") @db.Decimal(10, 2)\n  mileageSource        MileageSource? @map(\"mileage_source\")\n  createdById          String?        @map(\"created_by_id\") @db.Uuid // NEW (Wave 2)\n  updatedById          String?        @map(\"updated_by_id\") @db.Uuid // NEW (Wave 2)\n  deletedAt            DateTime?      @map(\"deleted_at\") @db.Timestamptz\n  deletedById          String?        @map(\"deleted_by_id\") @db.Uuid\n  createdAt            DateTime       @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt            DateTime       @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  tenant           Tenant            @relation(fields: [orgId], references: [id])\n  createdBy        User?             @relation(name: \"CarrierLoadCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull) // NEW\n  updatedBy        User?             @relation(name: \"CarrierLoadUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull) // NEW\n  deletedBy        User?             @relation(name: \"CarrierLoadDeletedBy\", fields: [deletedById], references: [id], onDelete: SetNull)\n  dispatch         Trip?             @relation(fields: [dispatchId], references: [id])\n  contract         CarrierContract?  @relation(fields: [contractId], references: [id])\n  client           CarrierClient     @relation(fields: [clientId], references: [id])\n  stops            CarrierStop[]\n  expenses         CarrierExpense[]\n  driverPayRecords DriverPayRecord[]\n  documents        CarrierDocument[]\n\n  // Driver Pay reverse relations\n  driverAssignments LoadDriverAssignment[]\n  payComponents     LoadPayComponent[]\n\n  @@index([clientId])\n  @@index([dispatchId])\n  @@index([status])\n  @@index([createdAt])\n  @@index([orgId])\n  @@index([deletedAt])\n  @@map(\"loads\")\n}\n\nmodel CarrierStop {\n  id                   String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  dispatchId           String    @map(\"dispatch_id\") @db.Uuid\n  loadId               String?   @map(\"load_id\") @db.Uuid\n  sequenceOrder        Int       @map(\"sequence_order\")\n  stopType             String    @map(\"stop_type\")\n  facilityId           String    @map(\"facility_id\") @db.Uuid\n  clientId             String?   @map(\"client_id\") @db.Uuid\n  appointmentStart     DateTime? @map(\"appointment_start\") @db.Timestamptz\n  appointmentEnd       DateTime? @map(\"appointment_end\") @db.Timestamptz\n  // Firm-vs-soft appointment window (spec Section 9). false = soft; optimisation\n  // treats a firm window as a hard constraint. Migration\n  // 20260802230853_add_appointment_is_firm — see DEC-8.\n  appointmentIsFirm    Boolean   @default(false) @map(\"appointment_is_firm\")\n  arrivedAt            DateTime? @map(\"arrived_at\") @db.Timestamptz\n  departedAt           DateTime? @map(\"departed_at\") @db.Timestamptz\n  status               String    @default(\"pending\")\n  skipReason           String?   @map(\"skip_reason\")\n  commodityDescription String?   @map(\"commodity_description\")\n  pieces               Int?\n  weightLbs            Decimal?  @map(\"weight_lbs\") @db.Decimal(10, 2)\n  bolNumber            String?   @map(\"bol_number\")\n  podNumber            String?   @map(\"pod_number\")\n  sealNumber           String?   @map(\"seal_number\")\n  bolRequired          Boolean   @default(true)\n  podRequired          Boolean   @default(true)\n  contactName          String?   @map(\"contact_name\")\n  contactPhone         String?   @map(\"contact_phone\")\n  specialInstructions  String?   @map(\"special_instructions\")\n  notes                String?\n  // Driver Pay additions (Phase 1)\n  freeTimeMinutes      Int       @default(120) @map(\"free_time_minutes\")\n  workState            String?   @map(\"work_state\") @db.VarChar(2)\n  // Workflow Engine checklist integration (quick-403)\n  checklistStatus      String?   @map(\"checklist_status\") // pending | in_progress | completed | deferred\n  deferredReason       String?   @map(\"deferred_reason\") // Why stop completion was deferred\n  checklistEntityId    String?   @map(\"checklist_entity_id\") @db.Uuid // FK to PlaybookInstance when workflow engine supports stops\n  // ─── Document Import (Phase 1, spec Sections 6 + 10) ──────────────────────\n  // JSONB rather than three child tables: this data is never queried relationally,\n  // and the scalar bolNumber/podNumber/pieces/weightLbs fields above stay populated\n  // in parallel so invoicing and reports keep working unchanged (audit B6).\n  // Mapped to stop_references: `references` is a reserved word in Postgres.\n  references           Json      @default(\"[]\") @map(\"stop_references\") // [{ type: SHIPMENT|PRO|ORDER|PO|BOL|LOAD|SEAL|OTHER, value }]\n  lineItems            Json      @default(\"[]\") @map(\"line_items\") // [{ sku, description, quantity, uom, weight, hazmat }]\n  pageNumbers          Json      @default(\"[]\") @map(\"page_numbers\") // source pages, so stop 5 opens page 4 not a 16-page scan\n  /// True for the pinned final stop of the day (spec Section 9). Modelled as a flag\n  /// because stops.stop_type is CHECK-constrained and has no \"end\" value (audit B5).\n  isEndStop            Boolean   @default(false) @map(\"is_end_stop\")\n  /// Set when a rollup was hand-edited away from the computed line-item total,\n  /// so the UI can mark it as overridden (spec Section 10).\n  rollupOverridden     Boolean   @default(false) @map(\"rollup_overridden\")\n  createdById          String?   @map(\"created_by_id\") @db.Uuid // NEW (Wave 2)\n  updatedById          String?   @map(\"updated_by_id\") @db.Uuid // NEW (Wave 2)\n  createdAt            DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt            DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  dispatch  Trip              @relation(fields: [dispatchId], references: [id])\n  createdBy User?             @relation(name: \"CarrierStopCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull) // NEW\n  updatedBy User?             @relation(name: \"CarrierStopUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull) // NEW\n  load      CarrierLoad?      @relation(fields: [loadId], references: [id])\n  facility  CarrierFacility   @relation(fields: [facilityId], references: [id])\n  client    CarrierClient?    @relation(fields: [clientId], references: [id])\n  documents CarrierDocument[]\n  expenses  CarrierExpense[]\n  messages  FleetMessage[]\n\n  @@unique([dispatchId, sequenceOrder])\n  @@index([dispatchId])\n  @@index([loadId])\n  @@index([clientId])\n  @@index([status])\n  @@index([dispatchId, sequenceOrder])\n  @@map(\"stops\")\n}\n\nmodel CarrierDocument {\n  id             String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  parentType     String    @map(\"parent_type\")\n  parentId       String    @map(\"parent_id\") @db.Uuid\n  stopId         String?   @map(\"stop_id\") @db.Uuid\n  clientId       String?   @map(\"client_id\") @db.Uuid\n  documentTypeId String?   @map(\"document_type_id\") @db.Uuid\n  loadId         String?   @map(\"load_id\") @db.Uuid\n  dispatchId     String?   @map(\"dispatch_id\") @db.Uuid\n  contractId     String?   @map(\"contract_id\") @db.Uuid\n  documentType   String    @map(\"document_type\")\n  fileUrl        String    @map(\"file_url\")\n  filename       String\n  fileSizeBytes  Int?      @map(\"file_size_bytes\")\n  uploadedBy     String    @map(\"uploaded_by\") @db.Uuid\n  verified       Boolean   @default(false)\n  verifiedBy     String?   @map(\"verified_by\") @db.Uuid\n  verifiedAt     DateTime? @map(\"verified_at\") @db.Timestamptz\n  notes          String?\n  createdAt      DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz\n\n  uploader        User                 @relation(name: \"CarrierDocUploader\", fields: [uploadedBy], references: [id])\n  verifier        User?                @relation(name: \"CarrierDocVerifier\", fields: [verifiedBy], references: [id])\n  stop            CarrierStop?         @relation(fields: [stopId], references: [id])\n  client          CarrierClient?       @relation(fields: [clientId], references: [id])\n  documentTypeRef CarrierDocumentType? @relation(fields: [documentTypeId], references: [id])\n  load            CarrierLoad?         @relation(fields: [loadId], references: [id])\n  dispatch        Trip?                @relation(fields: [dispatchId], references: [id])\n  contract        CarrierContract?     @relation(fields: [contractId], references: [id])\n  expenses        CarrierExpense[]\n\n  @@index([parentType, parentId])\n  @@index([stopId])\n  @@index([clientId])\n  @@index([documentTypeId])\n  @@index([loadId])\n  @@index([dispatchId])\n  @@index([contractId])\n  @@map(\"carrier_documents\")\n}\n\nmodel CarrierDocumentType {\n  id        String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId     String   @map(\"org_id\") @db.Uuid\n  name      String\n  slug      String\n  isDefault Boolean  @default(false) @map(\"is_default\")\n  isActive  Boolean  @default(true) @map(\"is_active\")\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz\n\n  tenant    Tenant            @relation(fields: [orgId], references: [id])\n  documents CarrierDocument[]\n\n  @@unique([orgId, slug])\n  @@index([orgId])\n  @@map(\"carrier_document_types\")\n}\n\n// ─── Document Import Models (Phase 1) ────────────────────────────────────────\n// Spec: docs/specs/DocumentImport_TechnicalSpec_v1.md Sections 5, 6, 14, 15\n// Audit: .planning/document-import/00-AUDIT.md\n// Tenant column follows the carrier sibling convention: org_id (NOT tenantId).\n\n/// One row per upload session. `reviewedExtraction` is what commits — edits live\n/// there rather than in a normalised staging table, so resume-after-close works\n/// for free (spec Section 6).\nmodel DocumentImport {\n  id     String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId  String @map(\"org_id\") @db.Uuid\n  status String @default(\"UPLOADED\")\n\n  /// Ordered tenant-prefixed storage keys for the source files, as uploaded.\n  sourceFileKeys String[] @default([]) @map(\"source_file_keys\")\n  sourceMimeType String?  @map(\"source_mime_type\")\n  originalName   String?  @map(\"original_name\")\n\n  /// SHA-256 over the concatenated source bytes. Half of the dedupe key.\n  contentHash    String    @map(\"content_hash\")\n  documentNumber String?   @map(\"document_number\")\n  /// Date parsed out of the document, not the upload date. Spec 1.2 callout (3):\n  /// a date can sit in a field labelled \"Number\", so this is deliberately separate.\n  documentDate   DateTime? @map(\"document_date\") @db.Date\n\n  documentType String? @map(\"document_type\")\n\n  clientId          String? @map(\"client_id\") @db.Uuid\n  contractId        String? @map(\"contract_id\") @db.Uuid\n  routeTemplateId   String? @map(\"route_template_id\") @db.Uuid\n  documentProfileId String? @map(\"document_profile_id\") @db.Uuid\n\n  /// How each resolved slot came to be resolved, written by whichever code path\n  /// committed it: `{ client: { via, score, matchedText, byUserId, at }, contract: {...} }`.\n  /// The \"why\" affordance renders from this rather than inferring from the fact\n  /// that an id is set — a machine-committed client is not a human's choice, and\n  /// saying so would be a lie about who decided. Null on rows written before the\n  /// column existed; those fall back to the original copy.\n  resolutionProvenance Json? @map(\"resolution_provenance\")\n\n  /// Model output, untouched. Holds third-party PII — subject to a retention\n  /// window (spec Section 15); committed entities are the record of truth.\n  rawExtraction      Json? @map(\"raw_extraction\")\n  /// Human-reviewed shape. THIS is what commits.\n  reviewedExtraction Json? @map(\"reviewed_extraction\")\n  extractionWarnings Json  @default(\"[]\") @map(\"extraction_warnings\")\n\n  modelIdentifier String?  @map(\"model_identifier\")\n  inputTokens     Int?     @map(\"input_tokens\")\n  outputTokens    Int?     @map(\"output_tokens\")\n  /// Money as Decimal, never float (spec Section 15).\n  costUsd         Decimal? @map(\"cost_usd\") @db.Decimal(10, 6)\n\n  pageCount      Int?    @map(\"page_count\")\n  cachedPages    Int     @default(0) @map(\"cached_pages\")\n  failureCode    String? @map(\"failure_code\")\n  failureMessage String? @map(\"failure_message\")\n\n  /// Entity ids written by the commit transaction, for audit and rollback proof.\n  createdTripId    String?   @map(\"created_trip_id\") @db.Uuid\n  createdEntityIds Json      @default(\"{}\") @map(\"created_entity_ids\")\n  committedAt      DateTime? @map(\"committed_at\") @db.Timestamptz\n\n  createdById String?   @map(\"created_by_id\") @db.Uuid\n  updatedById String?   @map(\"updated_by_id\") @db.Uuid\n  deletedAt   DateTime? @map(\"deleted_at\") @db.Timestamptz\n  deletedById String?   @map(\"deleted_by_id\") @db.Uuid\n  createdAt   DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt   DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  tenant          Tenant           @relation(fields: [orgId], references: [id])\n  createdBy       User?            @relation(name: \"DocumentImportCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy       User?            @relation(name: \"DocumentImportUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n  deletedBy       User?            @relation(name: \"DocumentImportDeletedBy\", fields: [deletedById], references: [id], onDelete: SetNull)\n  client          CarrierClient?   @relation(fields: [clientId], references: [id])\n  contract        CarrierContract? @relation(fields: [contractId], references: [id])\n  routeTemplate   RouteTemplate?   @relation(fields: [routeTemplateId], references: [id])\n  documentProfile DocumentProfile? @relation(fields: [documentProfileId], references: [id])\n\n  extractedPages     DocumentImportPage[]\n  externalReferences FacilityExternalReference[]\n  sourcedTemplates   RouteTemplate[]             @relation(name: \"RouteTemplateSourceImport\")\n  trips              Trip[]                      @relation(name: \"TripSourceImport\")\n\n  @@index([orgId])\n  @@index([status])\n  @@index([clientId])\n  @@index([deletedAt])\n  @@index([orgId, createdAt(sort: Desc)])\n  @@map(\"document_imports\")\n}\n\n/// Per-page extraction cache. Hashing each page independently means re-running a\n/// 16-page manifest where one page was re-shot bills for one page (spec Section 14).\nmodel DocumentImportPage {\n  id       String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId    String @map(\"org_id\") @db.Uuid\n  importId String @map(\"import_id\") @db.Uuid\n\n  pageNumber Int     @map(\"page_number\")\n  pageHash   String  @map(\"page_hash\")\n  storageKey String? @map(\"storage_key\")\n\n  /// Null while pending; populated by the extractor or copied from a cache hit.\n  extraction Json?\n  wasCached  Boolean @default(false) @map(\"was_cached\")\n\n  modelIdentifier String? @map(\"model_identifier\")\n  inputTokens     Int?    @map(\"input_tokens\")\n  outputTokens    Int?    @map(\"output_tokens\")\n\n  failureCode    String? @map(\"failure_code\")\n  failureMessage String? @map(\"failure_message\")\n  /// What the model actually sent when the reply could not be parsed, truncated\n  /// at RAW_RESPONSE_LIMIT (20KB) by the extractor. Diagnostic only — never\n  /// shown to a user. `failure_message` stays human-readable.\n  rawResponse    String? @map(\"raw_response\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  tenant Tenant         @relation(fields: [orgId], references: [id])\n  import DocumentImport @relation(fields: [importId], references: [id], onDelete: Cascade)\n\n  @@unique([importId, pageNumber])\n  @@index([orgId])\n  @@index([importId])\n  @@index([orgId, pageHash])\n  @@map(\"document_import_pages\")\n}\n\n/// The highest-value table in the module. \"43775\" is Dealer Tire's permanent id for\n/// a dealership — confirm once, resolve silently forever (spec Sections 1.5, 7).\nmodel FacilityExternalReference {\n  id         String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId      String @map(\"org_id\") @db.Uuid\n  clientId   String @map(\"client_id\") @db.Uuid\n  sourceCode String @map(\"source_code\")\n  facilityId String @map(\"facility_id\") @db.Uuid\n\n  /// How this link came to exist: T1/T2/T3/T4 of the resolution ladder.\n  resolvedVia    String? @map(\"resolved_via\")\n  sourceImportId String? @map(\"source_import_id\") @db.Uuid\n  /// Name as it appeared on the document when confirmed — evidence for the \"why\"\n  /// affordance (spec Section 4.2).\n  sourceName     String? @map(\"source_name\")\n\n  confirmedById String?  @map(\"confirmed_by_id\") @db.Uuid\n  createdById   String?  @map(\"created_by_id\") @db.Uuid\n  updatedById   String?  @map(\"updated_by_id\") @db.Uuid\n  createdAt     DateTime @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt     DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  tenant       Tenant          @relation(fields: [orgId], references: [id])\n  client       CarrierClient   @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  facility     CarrierFacility @relation(fields: [facilityId], references: [id], onDelete: Cascade)\n  sourceImport DocumentImport? @relation(fields: [sourceImportId], references: [id], onDelete: SetNull)\n  confirmedBy  User?           @relation(name: \"FacilityExternalRefConfirmedBy\", fields: [confirmedById], references: [id], onDelete: SetNull)\n\n  @@unique([orgId, clientId, sourceCode])\n  @@index([orgId])\n  @@index([clientId])\n  @@index([facilityId])\n  @@map(\"facility_external_references\")\n}\n\n/// Per tenant + client + document type. Holds extraction hints, the saved\n/// spreadsheet column mapping, and commit defaults (spec Section 6).\nmodel DocumentProfile {\n  id           String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId        String @map(\"org_id\") @db.Uuid\n  clientId     String @map(\"client_id\") @db.Uuid\n  documentType String @map(\"document_type\")\n\n  name String?\n\n  /// Free-form hints fed into the extraction prompt for this client's layout.\n  extractionHints Json @default(\"{}\") @map(\"extraction_hints\")\n  /// Saved header→canonical-path mapping for the spreadsheet path. Map once,\n  /// reuse silently (spec Section 5).\n  columnMapping   Json @default(\"{}\") @map(\"column_mapping\")\n\n  commitStrategy       String? @map(\"commit_strategy\")\n  defaultEndStopPolicy String? @map(\"default_end_stop_policy\")\n  pinnedContractId     String? @map(\"pinned_contract_id\") @db.Uuid\n\n  createdById String?   @map(\"created_by_id\") @db.Uuid\n  updatedById String?   @map(\"updated_by_id\") @db.Uuid\n  deletedAt   DateTime? @map(\"deleted_at\") @db.Timestamptz\n  createdAt   DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt   DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  tenant         Tenant           @relation(fields: [orgId], references: [id])\n  client         CarrierClient    @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  pinnedContract CarrierContract? @relation(name: \"DocumentProfilePinnedContract\", fields: [pinnedContractId], references: [id], onDelete: SetNull)\n\n  imports DocumentImport[]\n\n  @@unique([orgId, clientId, documentType])\n  @@index([orgId])\n  @@index([clientId])\n  @@map(\"document_profiles\")\n}\n\n/// The persistent half of the route-optimisation distance matrix cache\n/// (spec Section 9: *\"cache the matrix per ordered facility set\"*).\n///\n/// `facility_key` is the SORTED facility-id list, so invalidation is structural:\n/// a different set is a different key. L1 lives in process memory\n/// (`optimisation-matrix.ts`); this is L2, and its whole purpose is to survive a\n/// deploy, a cold start and a second instance.\n///\n/// Three things about the shape, all of them deliberate:\n///\n///  - **There is no `updated_at` column**, so there is no `@updatedAt`. A cache\n///    HIT must not write, which is what keeps the read paths read-only, so\n///    `computed_at` genuinely means \"when the provider was asked\" and the TTL is\n///    measured from that.\n///  - **No tenant relation.** `org_id` is scoped in every `where`, but the table\n///    is a derived cache and there is no FK on it in the database; declaring a\n///    relation would invent one Prisma then believes in.\n///  - Every column here was **read off production** (`information_schema`) before\n///    this model was written, not inferred from the neighbours.\nmodel RouteMatrixCache {\n  id          String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId       String   @map(\"org_id\") @db.Uuid\n  facilityKey String   @map(\"facility_key\")\n  miles       Json\n  minutes     Json\n  computedAt  DateTime @default(now()) @map(\"computed_at\") @db.Timestamptz\n\n  @@unique([orgId, facilityKey], map: \"route_matrix_cache_org_key_unique\")\n  @@index([orgId], map: \"route_matrix_cache_org_idx\")\n  @@map(\"route_matrix_cache\")\n}\n\nmodel CarrierExpense {\n  id                String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  dispatchId        String?   @map(\"dispatch_id\") @db.Uuid\n  loadId            String?   @map(\"load_id\") @db.Uuid\n  stopId            String?   @map(\"stop_id\") @db.Uuid\n  clientId          String?   @map(\"client_id\") @db.Uuid\n  expenseType       String    @map(\"expense_type\")\n  amount            Decimal   @db.Decimal(10, 2)\n  currency          String    @default(\"USD\")\n  paidBy            String    @map(\"paid_by\")\n  driverId          String?   @map(\"driver_id\") @db.Uuid\n  receiptDocumentId String?   @map(\"receipt_document_id\") @db.Uuid\n  submittedAt       DateTime? @map(\"submitted_at\") @db.Timestamptz\n  approvedBy        String?   @map(\"approved_by\") @db.Uuid\n  approvedAt        DateTime? @map(\"approved_at\") @db.Timestamptz\n  reimbursable      Boolean   @default(true)\n  notes             String?\n  orgId             String    @map(\"org_id\") @db.Uuid\n  createdById       String?   @map(\"created_by_id\") @db.Uuid // NEW (Wave 2)\n  updatedById       String?   @map(\"updated_by_id\") @db.Uuid // NEW (Wave 2)\n  createdAt         DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz\n\n  tenant          Tenant           @relation(fields: [orgId], references: [id])\n  createdBy       User?            @relation(name: \"CarrierExpenseCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull) // NEW\n  updatedBy       User?            @relation(name: \"CarrierExpenseUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull) // NEW\n  dispatch        Trip?            @relation(fields: [dispatchId], references: [id])\n  load            CarrierLoad?     @relation(fields: [loadId], references: [id])\n  stop            CarrierStop?     @relation(fields: [stopId], references: [id])\n  client          CarrierClient?   @relation(fields: [clientId], references: [id])\n  driver          CarrierDriver?   @relation(fields: [driverId], references: [id])\n  receiptDocument CarrierDocument? @relation(fields: [receiptDocumentId], references: [id])\n  approver        User?            @relation(name: \"CarrierExpenseApprover\", fields: [approvedBy], references: [id])\n\n  @@index([dispatchId])\n  @@index([loadId])\n  @@index([driverId])\n  @@index([clientId])\n  @@index([orgId])\n  @@map(\"carrier_expenses\")\n}\n\nmodel DriverPayRecord {\n  id                String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  driverId          String    @map(\"driver_id\") @db.Uuid\n  dispatchId        String?   @map(\"dispatch_id\") @db.Uuid\n  loadId            String?   @map(\"load_id\") @db.Uuid\n  clientId          String?   @map(\"client_id\") @db.Uuid\n  payModel          String    @map(\"pay_model\")\n  loadedMiles       Int?      @map(\"loaded_miles\")\n  emptyMiles        Int?      @map(\"empty_miles\")\n  loadedRate        Decimal?  @map(\"loaded_rate\") @db.Decimal(8, 4)\n  emptyRate         Decimal?  @map(\"empty_rate\") @db.Decimal(8, 4)\n  hoursWorked       Decimal?  @map(\"hours_worked\") @db.Decimal(6, 2)\n  hourlyRate        Decimal?  @map(\"hourly_rate\") @db.Decimal(8, 2)\n  grossRevenue      Decimal?  @map(\"gross_revenue\") @db.Decimal(12, 2)\n  percentageApplied Decimal?  @map(\"percentage_applied\") @db.Decimal(5, 4)\n  flatAmount        Decimal?  @map(\"flat_amount\") @db.Decimal(10, 2)\n  basePay           Decimal   @default(0) @map(\"base_pay\") @db.Decimal(10, 2)\n  bonuses           Decimal   @default(0)\n  tips              Decimal   @default(0)\n  deductions        Decimal   @default(0)\n  reimbursements    Decimal   @default(0)\n  netPay            Decimal   @default(0) @map(\"net_pay\") @db.Decimal(10, 2)\n  payPeriodStart    DateTime? @map(\"pay_period_start\") @db.Date\n  payPeriodEnd      DateTime? @map(\"pay_period_end\") @db.Date\n  status            String    @default(\"pending\")\n  approvedBy        String?   @map(\"approved_by\") @db.Uuid\n  approvedAt        DateTime? @map(\"approved_at\") @db.Timestamptz\n  notes             String?\n  orgId             String    @map(\"org_id\") @db.Uuid\n  createdAt         DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz\n\n  tenant   Tenant         @relation(fields: [orgId], references: [id])\n  driver   CarrierDriver  @relation(fields: [driverId], references: [id])\n  dispatch Trip?          @relation(fields: [dispatchId], references: [id])\n  load     CarrierLoad?   @relation(fields: [loadId], references: [id])\n  client   CarrierClient? @relation(fields: [clientId], references: [id])\n  approver User?          @relation(name: \"DriverPayApprover\", fields: [approvedBy], references: [id])\n\n  @@index([driverId])\n  @@index([dispatchId])\n  @@index([status])\n  @@index([payPeriodStart])\n  @@map(\"driver_pay_records\")\n}\n\nmodel CarrierCatalogMeta {\n  id           String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  enumGroup    String  @map(\"enum_group\")\n  enumValue    String  @map(\"enum_value\")\n  displayLabel String  @map(\"display_label\")\n  sortOrder    Int     @default(0) @map(\"sort_order\")\n  active       Boolean @default(true)\n\n  @@unique([enumGroup, enumValue])\n  @@map(\"carrier_catalog_meta\")\n}\n\nmodel InAppNotification {\n  id         String                @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orgId      String                @map(\"org_id\") @db.Uuid\n  userId     String?               @map(\"user_id\") @db.Uuid\n  type       InAppNotificationType\n  title      String                @db.VarChar(200)\n  message    String\n  entityType String                @map(\"entity_type\") @db.VarChar(50)\n  entityId   String                @map(\"entity_id\") @db.Uuid\n  read       Boolean               @default(false)\n  createdAt  DateTime              @default(now()) @map(\"created_at\") @db.Timestamptz\n\n  tenant Tenant @relation(fields: [orgId], references: [id])\n  user   User?  @relation(fields: [userId], references: [id])\n\n  @@unique([orgId, entityId, type])\n  @@index([orgId, read, createdAt(sort: Desc)])\n  @@index([orgId, createdAt(sort: Desc)])\n  @@map(\"in_app_notifications\")\n}\n\n// Workflow Engine Models\n\nmodel StepTemplate {\n  id            String       @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId      String       @db.Uuid\n  name          String       @db.VarChar(200)\n  description   String?\n  stepType      StepType\n  assigneeRole  AssigneeRole\n  defaultConfig Json         @default(\"{}\")\n  isActive      Boolean      @default(true)\n  deletedAt     DateTime?    @db.Timestamptz\n  createdAt     DateTime     @default(now()) @db.Timestamptz\n  updatedAt     DateTime     @updatedAt @db.Timestamptz\n  createdById   String?      @db.Uuid\n  updatedById   String?      @db.Uuid\n\n  tenant        Tenant         @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  playbookSteps PlaybookStep[]\n  stepInstances StepInstance[]\n  createdBy     User?          @relation(name: \"StepTemplateCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy     User?          @relation(name: \"StepTemplateUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([tenantId, isActive])\n  @@index([tenantId, stepType])\n}\n\nmodel Playbook {\n  id            String             @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId      String             @db.Uuid\n  name          String             @db.VarChar(200)\n  description   String?\n  entityType    PlaybookEntityType\n  category      PlaybookCategory\n  playbookPhase PhaseType          @default(NONE)\n  isActive      Boolean            @default(true)\n  deletedAt     DateTime?          @db.Timestamptz\n  createdAt     DateTime           @default(now()) @db.Timestamptz\n  updatedAt     DateTime           @updatedAt @db.Timestamptz\n  createdById   String?            @db.Uuid\n  updatedById   String?            @db.Uuid\n\n  tenant    Tenant             @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  steps     PlaybookStep[]\n  instances PlaybookInstance[]\n  triggers  PlaybookTrigger[]\n  createdBy User?              @relation(name: \"PlaybookCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User?              @relation(name: \"PlaybookUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([tenantId, isActive])\n  @@index([tenantId, entityType])\n}\n\nmodel PlaybookStep {\n  id                String           @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  playbookId        String           @db.Uuid\n  stepTemplateId    String           @db.Uuid\n  sequence          Int\n  playbookPhase     PhaseType        @default(NONE)\n  overrideConfig    Json             @default(\"{}\")\n  isRequired        Boolean          @default(true)\n  isDispatchBlocker Boolean          @default(false)\n  dueDaysFromStart  Int?\n  dueWithinHours    Int? // SLA in hours (e.g. 24). If null, cron skips this step.\n  overdueRecipient  OverdueRecipient @default(OWNER) // Who gets the overdue push notification\n  dueBeforeDispatch Boolean          @default(false)\n  createdAt         DateTime         @default(now()) @db.Timestamptz\n  updatedAt         DateTime         @updatedAt @db.Timestamptz\n  tenantId          String           @db.Uuid\n  createdBy         String?          @db.Uuid\n  updatedBy         String?          @db.Uuid\n  deletedAt         DateTime?        @db.Timestamptz\n  deletedBy         String?          @db.Uuid\n\n  playbook     Playbook     @relation(fields: [playbookId], references: [id], onDelete: Cascade)\n  stepTemplate StepTemplate @relation(fields: [stepTemplateId], references: [id], onDelete: Restrict)\n  tenant       Tenant       @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n  creator      User?        @relation(name: \"PlaybookStepCreatedBy\", fields: [createdBy], references: [id], onDelete: SetNull)\n\n  @@unique([playbookId, sequence])\n  @@index([playbookId])\n  @@index([stepTemplateId])\n  @@index([tenantId])\n}\n\nmodel PlaybookInstance {\n  id                String             @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId          String             @db.Uuid\n  playbookId        String             @db.Uuid\n  playbookSnapshot  Json\n  entityType        PlaybookEntityType\n  entityId          String             @db.Uuid\n  status            InstanceStatus     @default(NOT_STARTED)\n  completionPercent Float              @default(0)\n  isDispatchReady   Boolean            @default(false)\n  startedAt         DateTime?          @db.Timestamptz\n  completedAt       DateTime?          @db.Timestamptz\n  dueDate           DateTime?          @db.Timestamptz\n  triggeredBy       String? // 'manual' | 'trigger' — null for legacy rows\n  triggeredEvent    TriggerEvent? // Set when triggeredBy='trigger', e.g. ON_DRIVER_CREATE\n  createdAt         DateTime           @default(now()) @db.Timestamptz\n  updatedAt         DateTime           @updatedAt @db.Timestamptz\n  createdById       String?            @db.Uuid\n  updatedById       String?            @db.Uuid\n\n  tenant        Tenant                 @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  playbook      Playbook               @relation(fields: [playbookId], references: [id], onDelete: Restrict)\n  stepInstances StepInstance[]\n  notifications PlaybookNotification[]\n  createdBy     User?                  @relation(name: \"PlaybookInstanceCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy     User?                  @relation(name: \"PlaybookInstanceUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([tenantId, entityType, entityId])\n  @@index([tenantId, status])\n  @@index([tenantId, isDispatchReady])\n  @@index([tenantId, triggeredBy, createdAt(sort: Desc)])\n}\n\nmodel StepInstance {\n  id                 String       @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  playbookInstanceId String       @db.Uuid\n  stepTemplateId     String?      @db.Uuid\n  stepSnapshot       Json\n  status             StepStatus   @default(NOT_STARTED)\n  assigneeRole       AssigneeRole\n  assignedUserId     String?      @db.Uuid\n  completedByUserId  String?      @db.Uuid\n  completedAt        DateTime?    @db.Timestamptz\n  result             Json?\n  skipReason         String?\n  skippedByUserId    String?      @db.Uuid\n  dueDate            DateTime?    @db.Timestamptz\n  isOverdue          Boolean      @default(false)\n  createdAt          DateTime     @default(now()) @db.Timestamptz\n  updatedAt          DateTime     @updatedAt @db.Timestamptz\n  tenantId           String       @db.Uuid\n  createdBy          String?      @db.Uuid\n  updatedBy          String?      @db.Uuid\n  deletedAt          DateTime?    @db.Timestamptz\n  deletedBy          String?      @db.Uuid\n\n  playbookInstance PlaybookInstance @relation(fields: [playbookInstanceId], references: [id], onDelete: Cascade)\n  stepTemplate     StepTemplate?    @relation(fields: [stepTemplateId], references: [id], onDelete: Restrict)\n  tenant           Tenant           @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n  creator          User?            @relation(name: \"StepInstanceCreatedBy\", fields: [createdBy], references: [id], onDelete: SetNull)\n\n  @@index([playbookInstanceId])\n  @@index([assignedUserId, status])\n  @@index([playbookInstanceId, status])\n  @@index([tenantId])\n}\n\nmodel PlaybookNotification {\n  id                 String       @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId           String       @db.Uuid\n  playbookInstanceId String       @db.Uuid\n  stepInstanceId     String?      @db.Uuid\n  notificationType   NotifType\n  channel            NotifChannel\n  recipientUserId    String       @db.Uuid\n  message            String\n  sentAt             DateTime?    @db.Timestamptz\n  deliveredAt        DateTime?    @db.Timestamptz\n  createdAt          DateTime     @default(now()) @db.Timestamptz\n\n  tenant           Tenant           @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  playbookInstance PlaybookInstance @relation(fields: [playbookInstanceId], references: [id], onDelete: Cascade)\n\n  @@index([playbookInstanceId])\n  @@index([recipientUserId])\n}\n\n// ─── Phase 45 Automation Models ──────────────────────────────────────────────\n\nmodel PlaybookTrigger {\n  id              String       @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  playbookId      String       @db.Uuid\n  playbook        Playbook     @relation(fields: [playbookId], references: [id], onDelete: Cascade)\n  tenantId        String       @db.Uuid\n  tenant          Tenant       @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  triggerEvent    TriggerEvent\n  conditions      Json? // { driverType: \"CDL\" } — flat key-value only per spec Section 6.5\n  recurringConfig Json? // { frequency:\"daily\", daysOfWeek:[1..5], time:\"07:00\" } — reserved, not used in Phase 45\n  isActive        Boolean      @default(true)\n  createdAt       DateTime     @default(now()) @db.Timestamptz\n  updatedAt       DateTime     @updatedAt @db.Timestamptz\n  createdById     String?      @db.Uuid\n  updatedById     String?      @db.Uuid\n\n  createdBy User? @relation(name: \"PlaybookTriggerCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User? @relation(name: \"PlaybookTriggerUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([tenantId, triggerEvent])\n  @@index([playbookId])\n}\n\nmodel DispatchOverrideAudit {\n  id         String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId   String   @db.Uuid\n  tenant     Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  dispatchId String   @db.Uuid // Trip.id — no FK because Trip lives in a different module\n  userId     String   @db.Uuid // Admin user who approved the override\n  reason     String\n  entityType String // \"DRIVER\" or \"VEHICLE\"\n  entityId   String   @db.Uuid\n  createdAt  DateTime @default(now()) @db.Timestamptz\n\n  @@index([tenantId])\n  @@index([dispatchId])\n}\n\n// ─── Phase 47 Models ──────────────────────────────────────────────────────────\n\nmodel Plan {\n  id                String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  key               String   @unique\n  name              String\n  description       String?\n  defaultTrialDays  Int      @default(14)\n  monthlyPriceCents Int\n  yearlyPriceCents  Int?\n  maxTrucks         Int?\n  maxUsers          Int?\n  storageGbLimit    Int?\n  isActive          Boolean  @default(true)\n  sortOrder         Int      @default(0)\n  stripeProductId   String?\n  createdAt         DateTime @default(now()) @db.Timestamptz\n  updatedAt         DateTime @updatedAt @db.Timestamptz\n\n  subscriptions Subscription[]\n\n  @@index([isActive])\n}\n\nmodel Promo {\n  id              String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  code            String   @unique\n  description     String?\n  bonusTrialDays  Int      @default(0)\n  discountPct     Int?\n  activeFrom      DateTime @db.Timestamptz\n  activeTo        DateTime @db.Timestamptz\n  maxRedemptions  Int?\n  redemptionCount Int      @default(0)\n  isActive        Boolean  @default(true)\n  stripeCouponId  String?\n  createdAt       DateTime @default(now()) @db.Timestamptz\n  updatedAt       DateTime @updatedAt @db.Timestamptz\n\n  subscriptions Subscription[]\n\n  @@index([isActive])\n}\n\nmodel Subscription {\n  id                   String             @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId             String             @unique @db.Uuid\n  planId               String             @db.Uuid\n  promoId              String?            @db.Uuid\n  status               SubscriptionStatus @default(TRIALING)\n  trialEndsAt          DateTime           @db.Timestamptz\n  manualExtensionUntil DateTime?          @db.Timestamptz\n  currentPeriodStart   DateTime?          @db.Timestamptz\n  currentPeriodEnd     DateTime?          @db.Timestamptz\n  stripeCustomerId     String?\n  stripeSubscriptionId String?\n  cancelAtPeriodEnd    Boolean            @default(false)\n  createdAt            DateTime           @default(now()) @db.Timestamptz\n  updatedAt            DateTime           @updatedAt @db.Timestamptz\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  plan   Plan   @relation(fields: [planId], references: [id])\n  promo  Promo? @relation(fields: [promoId], references: [id])\n\n  @@index([tenantId])\n  @@index([status])\n  @@index([trialEndsAt])\n}\n\nmodel ActivationProgress {\n  id                     String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId               String    @unique @db.Uuid\n  accountCreatedAt       DateTime  @default(now()) @db.Timestamptz\n  firstRealTruckAt       DateTime? @db.Timestamptz\n  firstRealDriverAt      DateTime? @db.Timestamptz\n  firstRealClientAt      DateTime? @db.Timestamptz\n  firstRealLoadCreatedAt DateTime? @db.Timestamptz\n  firstLoadInTransitAt   DateTime? @db.Timestamptz\n  firstLoadDeliveredAt   DateTime? @db.Timestamptz\n  completionPct          Int       @default(20)\n  isActivated            Boolean   @default(false)\n  congratsShownAt        DateTime? @db.Timestamptz\n  createdAt              DateTime  @default(now()) @db.Timestamptz\n  updatedAt              DateTime  @updatedAt @db.Timestamptz\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId])\n  @@index([isActivated])\n}\n\nmodel AutomationRule {\n  id               String          @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  key              String          @unique\n  name             String\n  description      String?\n  triggerEvent     String\n  conditionsJson   Json            @default(\"{}\")\n  actionsJson      Json\n  scope            AutomationScope @default(SYSTEM)\n  tenantId         String?         @db.Uuid\n  isActive         Boolean         @default(true)\n  runOncePerTenant Boolean         @default(true)\n  delaySeconds     Int             @default(0)\n  createdAt        DateTime        @default(now()) @db.Timestamptz\n  updatedAt        DateTime        @updatedAt @db.Timestamptz\n\n  tenant Tenant?         @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  runs   AutomationRun[]\n\n  @@index([triggerEvent, isActive])\n  @@index([tenantId])\n}\n\nmodel AutomationRun {\n  id           String              @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  ruleId       String?             @db.Uuid\n  tenantId     String              @db.Uuid\n  userId       String?             @db.Uuid\n  triggeredBy  String\n  status       AutomationRunStatus\n  resultJson   Json?\n  firedAt      DateTime            @default(now()) @db.Timestamptz\n  scheduledAt  DateTime?           @db.Timestamptz\n  eventId      String?             @db.Uuid\n  errorMessage String?\n\n  rule   AutomationRule? @relation(fields: [ruleId], references: [id], onDelete: SetNull)\n  tenant Tenant          @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([ruleId])\n  @@index([tenantId])\n  @@index([firedAt])\n  @@index([eventId, ruleId])\n  @@index([status, scheduledAt])\n}\n\nmodel AppEvent {\n  id         String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId   String   @db.Uuid\n  userId     String?  @db.Uuid\n  eventType  String\n  properties Json     @default(\"{}\")\n  createdAt  DateTime @default(now()) @db.Timestamptz\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId, createdAt])\n  @@index([eventType, createdAt])\n  @@index([userId, createdAt])\n}\n\nmodel TenantMetricsDaily {\n  id             String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId       String   @db.Uuid\n  date           DateTime @db.Date\n  dauCount       Int      @default(0)\n  sessionCount   Int      @default(0)\n  keyActionCount Int      @default(0)\n  storageBytes   BigInt   @default(0)\n  seatsUsed      Int      @default(0)\n  loadsCreated   Int      @default(0)\n  loadsInTransit Int      @default(0)\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@unique([tenantId, date])\n  @@index([tenantId])\n  @@index([date])\n}\n\nmodel TenantHealthScore {\n  id             String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId       String   @unique @db.Uuid\n  score          Int\n  topFactorsJson Json\n  computedAt     DateTime @default(now()) @db.Timestamptz\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([score])\n}\n\n// ─── Driver Pay Models (Phase 1) ─────────────────────────────────────────────\n\nmodel DriverCompensationTemplate {\n  id                     String         @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId               String         @map(\"tenant_id\") @db.Uuid\n  driverId               String         @map(\"driver_id\") @db.Uuid\n  employmentType         EmploymentType @map(\"employment_type\")\n  payType                DriverPayType  @map(\"pay_type\")\n  baseRate               Decimal        @map(\"base_rate\") @db.Decimal(10, 4)\n  rateUnit               RateUnit       @map(\"rate_unit\")\n  loadedMilesOnly        Boolean        @map(\"loaded_miles_only\")\n  fuelSurchargeRate      Decimal?       @map(\"fuel_surcharge_rate\") @db.Decimal(10, 4)\n  perDiemEnabled         Boolean        @map(\"per_diem_enabled\")\n  perDiemRate            Decimal?       @map(\"per_diem_rate\") @db.Decimal(8, 2)\n  overtimeEligible       Boolean        @map(\"overtime_eligible\")\n  overtimeThresholdHours Decimal?       @map(\"overtime_threshold_hours\") @db.Decimal(5, 2)\n  overtimeMultiplier     Decimal?       @map(\"overtime_multiplier\") @db.Decimal(4, 2)\n  dailyOvertimeThreshold Decimal?       @map(\"daily_overtime_threshold\") @db.Decimal(4, 2)\n  weeklyEarningGoal      Decimal?       @map(\"weekly_earning_goal\") @db.Decimal(10, 2)\n  currency               String         @default(\"USD\") @map(\"currency\") @db.VarChar(3)\n  effectiveFrom          DateTime       @map(\"effective_from\") @db.Date\n  effectiveTo            DateTime?      @map(\"effective_to\") @db.Date\n  notes                  String?\n  // Standard tenant columns\n  createdAt              DateTime       @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt              DateTime       @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  createdBy              String?        @map(\"created_by\") @db.Uuid\n  updatedBy              String?        @map(\"updated_by\") @db.Uuid\n  deletedAt              DateTime?      @map(\"deleted_at\") @db.Timestamptz(6)\n\n  tenant      Tenant                 @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n  driver      CarrierDriver          @relation(fields: [driverId], references: [id], onDelete: Restrict)\n  assignments LoadDriverAssignment[]\n  creator     User?                  @relation(name: \"DriverCompensationTemplateCreatedBy\", fields: [createdBy], references: [id], onDelete: SetNull)\n  updater     User?                  @relation(name: \"DriverCompensationTemplateUpdatedBy\", fields: [updatedBy], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([driverId])\n  @@index([tenantId, driverId])\n  @@map(\"driver_compensation_templates\")\n}\n\nmodel LoadDriverAssignment {\n  id                     String                 @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId               String                 @map(\"tenant_id\") @db.Uuid\n  loadId                 String                 @map(\"load_id\") @db.Uuid\n  driverId               String                 @map(\"driver_id\") @db.Uuid\n  driverRole             DriverRole             @map(\"driver_role\")\n  templateId             String?                @map(\"template_id\") @db.Uuid\n  payType                DriverPayType          @map(\"pay_type\")\n  baseRate               Decimal                @map(\"base_rate\") @db.Decimal(10, 4)\n  rateUnit               RateUnit               @map(\"rate_unit\")\n  loadedMilesOnly        Boolean                @map(\"loaded_miles_only\")\n  fuelSurchargeRate      Decimal?               @map(\"fuel_surcharge_rate\") @db.Decimal(10, 4)\n  splitPercentage        Decimal?               @map(\"split_percentage\") @db.Decimal(5, 2)\n  perDiemEnabled         Boolean                @map(\"per_diem_enabled\")\n  perDiemRate            Decimal?               @map(\"per_diem_rate\") @db.Decimal(8, 2)\n  overrideReason         String?                @map(\"override_reason\")\n  estimatedMiles         Decimal?               @map(\"estimated_miles\") @db.Decimal(10, 2)\n  actualMiles            Decimal?               @map(\"actual_miles\") @db.Decimal(10, 2)\n  mileageSource          MileageSource?         @map(\"mileage_source\")\n  mileageSourceReference String?                @map(\"mileage_source_reference\") @db.VarChar(255)\n  estimatedHours         Decimal?               @map(\"estimated_hours\") @db.Decimal(8, 2)\n  actualHours            Decimal?               @map(\"actual_hours\") @db.Decimal(8, 2)\n  loadRevenue            Decimal?               @map(\"load_revenue\") @db.Decimal(12, 2)\n  payStatus              DriverAssignmentStatus @default(DRAFT) @map(\"pay_status\")\n  settlementId           String?                @map(\"settlement_id\") @db.Uuid\n  approvedBy             String?                @map(\"approved_by\") @db.Uuid\n  approvedAt             DateTime?              @map(\"approved_at\") @db.Timestamptz(6)\n  paidAt                 DateTime?              @map(\"paid_at\") @db.Timestamptz(6)\n  currency               String                 @default(\"USD\") @map(\"currency\") @db.VarChar(3)\n  // Standard tenant columns\n  createdAt              DateTime               @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt              DateTime               @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  createdBy              String?                @map(\"created_by\") @db.Uuid\n  updatedBy              String?                @map(\"updated_by\") @db.Uuid\n  deletedAt              DateTime?              @map(\"deleted_at\") @db.Timestamptz(6)\n\n  tenant        Tenant                      @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n  load          CarrierLoad                 @relation(fields: [loadId], references: [id], onDelete: Restrict)\n  driver        CarrierDriver               @relation(fields: [driverId], references: [id], onDelete: Restrict)\n  template      DriverCompensationTemplate? @relation(fields: [templateId], references: [id], onDelete: Restrict)\n  settlement    DriverSettlement?           @relation(fields: [settlementId], references: [id], onDelete: Restrict)\n  payComponents LoadPayComponent[]\n  attachments   PayComponentAttachment[]\n  creator       User?                       @relation(name: \"LoadDriverAssignmentCreatedBy\", fields: [createdBy], references: [id], onDelete: SetNull)\n  updater       User?                       @relation(name: \"LoadDriverAssignmentUpdatedBy\", fields: [updatedBy], references: [id], onDelete: SetNull)\n\n  // Uniqueness enforced by partial unique index in DB (only live rows);\n  // see migration apply-partial-unique-load-driver.sql\n  @@index([tenantId])\n  @@index([loadId])\n  @@index([driverId])\n  @@index([tenantId, driverId])\n  @@index([settlementId])\n  @@map(\"load_driver_assignments\")\n}\n\nmodel LoadPayComponent {\n  id                  String               @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId            String               @map(\"tenant_id\") @db.Uuid\n  assignmentId        String               @map(\"assignment_id\") @db.Uuid\n  loadId              String               @map(\"load_id\") @db.Uuid\n  driverId            String               @map(\"driver_id\") @db.Uuid\n  stopId              String?              @map(\"stop_id\") @db.Uuid\n  componentType       PayComponentType     @map(\"component_type\")\n  category            PayComponentCategory\n  description         String               @db.VarChar(255)\n  quantity            Decimal              @db.Decimal(10, 4)\n  unit                PayComponentUnit\n  rate                Decimal              @db.Decimal(10, 4)\n  multiplier          Decimal              @default(1.0) @db.Decimal(5, 2)\n  grossAmount         Decimal              @map(\"gross_amount\") @db.Decimal(12, 2)\n  isTaxable           Boolean              @map(\"is_taxable\")\n  isReimbursement     Boolean              @map(\"is_reimbursement\")\n  originalComponentId String?              @map(\"original_component_id\") @db.Uuid\n  visibleToDriver     Boolean              @default(true) @map(\"visible_to_driver\")\n  notes               String?\n  enteredBy           String               @map(\"entered_by\") @db.Uuid\n  // Standard tenant columns\n  createdAt           DateTime             @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt           DateTime             @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  createdBy           String?              @map(\"created_by\") @db.Uuid\n  updatedBy           String?              @map(\"updated_by\") @db.Uuid\n  deletedAt           DateTime?            @map(\"deleted_at\") @db.Timestamptz(6)\n\n  tenant      Tenant                   @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n  assignment  LoadDriverAssignment     @relation(fields: [assignmentId], references: [id], onDelete: Restrict)\n  load        CarrierLoad              @relation(fields: [loadId], references: [id], onDelete: Restrict)\n  original    LoadPayComponent?        @relation(\"ComponentCorrection\", fields: [originalComponentId], references: [id], onDelete: Restrict)\n  corrections LoadPayComponent[]       @relation(\"ComponentCorrection\")\n  attachments PayComponentAttachment[]\n  disputes    DriverDispute[]\n  creator     User?                    @relation(name: \"LoadPayComponentCreatedBy\", fields: [createdBy], references: [id], onDelete: SetNull)\n  updater     User?                    @relation(name: \"LoadPayComponentUpdatedBy\", fields: [updatedBy], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([assignmentId])\n  @@index([loadId])\n  @@index([driverId])\n  @@index([tenantId, driverId])\n  @@map(\"load_pay_components\")\n}\n\nmodel DriverBonus {\n  id                String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId          String    @map(\"tenant_id\") @db.Uuid\n  driverId          String    @map(\"driver_id\") @db.Uuid\n  bonusType         BonusType @map(\"bonus_type\")\n  amount            Decimal   @db.Decimal(12, 2)\n  description       String    @db.VarChar(255)\n  triggerDate       DateTime  @map(\"trigger_date\") @db.Date\n  scheduledPayDate  DateTime? @map(\"scheduled_pay_date\") @db.Date\n  paidAt            DateTime? @map(\"paid_at\") @db.Timestamptz(6)\n  installmentNumber Int?      @map(\"installment_number\")\n  totalInstallments Int?      @map(\"total_installments\")\n  parentBonusId     String?   @map(\"parent_bonus_id\") @db.Uuid\n  referredDriverId  String?   @map(\"referred_driver_id\") @db.Uuid\n  settlementId      String?   @map(\"settlement_id\") @db.Uuid\n  isTaxable         Boolean   @map(\"is_taxable\")\n  visibleToDriver   Boolean   @default(true) @map(\"visible_to_driver\")\n  notes             String?\n  // Standard tenant columns\n  createdAt         DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt         DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  createdBy         String?   @map(\"created_by\") @db.Uuid\n  updatedBy         String?   @map(\"updated_by\") @db.Uuid\n  deletedAt         DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  tenant         Tenant            @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n  driver         CarrierDriver     @relation(fields: [driverId], references: [id], onDelete: Restrict)\n  referredDriver CarrierDriver?    @relation(\"BonusReferredDriver\", fields: [referredDriverId], references: [id], onDelete: Restrict)\n  settlement     DriverSettlement? @relation(fields: [settlementId], references: [id], onDelete: Restrict)\n  parentBonus    DriverBonus?      @relation(\"BonusInstallment\", fields: [parentBonusId], references: [id], onDelete: Restrict)\n  childBonuses   DriverBonus[]     @relation(\"BonusInstallment\")\n  creator        User?             @relation(name: \"DriverBonusCreatedBy\", fields: [createdBy], references: [id], onDelete: SetNull)\n  updater        User?             @relation(name: \"DriverBonusUpdatedBy\", fields: [updatedBy], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([driverId])\n  @@index([tenantId, driverId])\n  @@index([settlementId])\n  @@map(\"driver_bonuses\")\n}\n\nmodel DriverDeduction {\n  id                 String            @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId           String            @map(\"tenant_id\") @db.Uuid\n  driverId           String            @map(\"driver_id\") @db.Uuid\n  deductionType      DeductionType     @map(\"deduction_type\")\n  schedule           DeductionSchedule\n  amountPerPeriod    Decimal           @map(\"amount_per_period\") @db.Decimal(12, 2)\n  totalAmount        Decimal?          @map(\"total_amount\") @db.Decimal(12, 2)\n  amountCollected    Decimal           @default(0) @map(\"amount_collected\") @db.Decimal(12, 2)\n  maxPercentageOfNet Decimal?          @map(\"max_percentage_of_net\") @db.Decimal(5, 2)\n  startsOn           DateTime          @map(\"starts_on\") @db.Date\n  endsOn             DateTime?         @map(\"ends_on\") @db.Date\n  paused             Boolean           @default(false)\n  visibleToDriver    Boolean           @default(true) @map(\"visible_to_driver\")\n  notes              String?\n  // Standard tenant columns\n  createdAt          DateTime          @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt          DateTime          @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  createdBy          String?           @map(\"created_by\") @db.Uuid\n  updatedBy          String?           @map(\"updated_by\") @db.Uuid\n  deletedAt          DateTime?         @map(\"deleted_at\") @db.Timestamptz(6)\n\n  tenant  Tenant        @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n  driver  CarrierDriver @relation(fields: [driverId], references: [id], onDelete: Restrict)\n  creator User?         @relation(name: \"DriverDeductionCreatedBy\", fields: [createdBy], references: [id], onDelete: SetNull)\n  updater User?         @relation(name: \"DriverDeductionUpdatedBy\", fields: [updatedBy], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([driverId])\n  @@index([tenantId, driverId])\n  @@map(\"driver_deductions\")\n}\n\n/// Note: partial unique index `ds_unique_period_active` on\n/// (driver_id, period_start, period_end) WHERE deleted_at IS NULL AND status <> 'VOIDED'\n/// is defined manually in migration 20260514000001_driver_settlements_partial_unique\n/// because Prisma does not support partial unique indexes natively.\n/// @@unique partial — do NOT add @@unique([driverId, periodStart, periodEnd]) here.\nmodel DriverSettlement {\n  id                     String                 @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId               String                 @map(\"tenant_id\") @db.Uuid\n  driverId               String                 @map(\"driver_id\") @db.Uuid\n  periodStart            DateTime               @map(\"period_start\") @db.Date\n  periodEnd              DateTime               @map(\"period_end\") @db.Date\n  status                 DriverSettlementStatus @default(DRAFT)\n  grossTaxable           Decimal                @map(\"gross_taxable\") @db.Decimal(12, 2)\n  grossNonTaxable        Decimal                @map(\"gross_non_taxable\") @db.Decimal(12, 2)\n  totalDeductions        Decimal                @map(\"total_deductions\") @db.Decimal(12, 2)\n  netPay                 Decimal                @map(\"net_pay\") @db.Decimal(12, 2)\n  finalizedBy            String?                @map(\"finalized_by\") @db.Uuid\n  finalizedAt            DateTime?              @map(\"finalized_at\") @db.Timestamptz(6)\n  paidAt                 DateTime?              @map(\"paid_at\") @db.Timestamptz(6)\n  settlementReference    String?                @map(\"settlement_reference\") @db.VarChar(100)\n  pdfUrl                 String?                @map(\"pdf_url\") @db.VarChar(500)\n  notes                  String?\n  employmentTypeSnapshot EmploymentType?        @map(\"employment_type_snapshot\")\n  // Standard tenant columns\n  createdAt              DateTime               @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt              DateTime               @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  createdBy              String?                @map(\"created_by\") @db.Uuid\n  updatedBy              String?                @map(\"updated_by\") @db.Uuid\n  deletedAt              DateTime?              @map(\"deleted_at\") @db.Timestamptz(6)\n\n  tenant      Tenant                 @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n  driver      CarrierDriver          @relation(fields: [driverId], references: [id], onDelete: Restrict)\n  assignments LoadDriverAssignment[]\n  bonuses     DriverBonus[]\n  creator     User?                  @relation(name: \"DriverSettlementCreatedBy\", fields: [createdBy], references: [id], onDelete: SetNull)\n  updater     User?                  @relation(name: \"DriverSettlementUpdatedBy\", fields: [updatedBy], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([driverId])\n  @@index([tenantId, driverId])\n  @@index([tenantId, periodStart])\n  @@index([tenantId, employmentTypeSnapshot])\n  @@map(\"driver_settlements\")\n}\n\nmodel PayComponentAttachment {\n  id           String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId     String    @map(\"tenant_id\") @db.Uuid\n  componentId  String    @map(\"component_id\") @db.Uuid\n  assignmentId String    @map(\"assignment_id\") @db.Uuid\n  storageKey   String    @map(\"storage_key\")\n  filename     String    @db.VarChar(255)\n  contentType  String?   @map(\"content_type\") @db.VarChar(100)\n  sizeBytes    Int?      @map(\"size_bytes\")\n  uploadedBy   String    @map(\"uploaded_by\") @db.Uuid\n  // Standard tenant columns\n  createdAt    DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt    DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  createdBy    String?   @map(\"created_by\") @db.Uuid\n  updatedBy    String?   @map(\"updated_by\") @db.Uuid\n  deletedAt    DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  tenant     Tenant               @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n  component  LoadPayComponent     @relation(fields: [componentId], references: [id], onDelete: Restrict)\n  assignment LoadDriverAssignment @relation(fields: [assignmentId], references: [id], onDelete: Restrict)\n  creator    User?                @relation(name: \"PayComponentAttachmentCreatedBy\", fields: [createdBy], references: [id], onDelete: SetNull)\n  updater    User?                @relation(name: \"PayComponentAttachmentUpdatedBy\", fields: [updatedBy], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([componentId])\n  @@index([assignmentId])\n  @@map(\"pay_component_attachments\")\n}\n\nmodel DriverDispute {\n  id                 String               @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId           String               @map(\"tenant_id\") @db.Uuid\n  driverId           String               @map(\"driver_id\") @db.Uuid\n  targetType         DisputeTargetType    @map(\"target_type\")\n  targetId           String               @map(\"target_id\") @db.Uuid\n  issueCategory      DisputeIssueCategory @map(\"issue_category\")\n  driverMessage      String               @map(\"driver_message\")\n  status             DisputeStatus        @default(OPEN)\n  assignedTo         String?              @map(\"assigned_to\") @db.Uuid\n  resolutionMessage  String?              @map(\"resolution_message\")\n  resolvedAt         DateTime?            @map(\"resolved_at\") @db.Timestamptz(6)\n  linkedCorrectionId String?              @map(\"linked_correction_id\") @db.Uuid\n  // Standard tenant columns\n  createdAt          DateTime             @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt          DateTime             @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  createdBy          String?              @map(\"created_by\") @db.Uuid\n  updatedBy          String?              @map(\"updated_by\") @db.Uuid\n  deletedAt          DateTime?            @map(\"deleted_at\") @db.Timestamptz(6)\n\n  tenant           Tenant            @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n  driver           CarrierDriver     @relation(fields: [driverId], references: [id], onDelete: Restrict)\n  linkedCorrection LoadPayComponent? @relation(fields: [linkedCorrectionId], references: [id], onDelete: Restrict)\n  creator          User?             @relation(name: \"DriverDisputeCreatedBy\", fields: [createdBy], references: [id], onDelete: SetNull)\n  updater          User?             @relation(name: \"DriverDisputeUpdatedBy\", fields: [updatedBy], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([driverId])\n  @@index([tenantId, driverId])\n  @@index([targetId])\n  @@map(\"driver_disputes\")\n}\n\nmodel DriverPayAuditLog {\n  id            String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId      String   @map(\"tenant_id\") @db.Uuid\n  entityType    String   @map(\"entity_type\") @db.VarChar(100)\n  entityId      String   @map(\"entity_id\") @db.Uuid\n  action        String   @db.VarChar(100)\n  previousValue Json?    @map(\"previous_value\")\n  newValue      Json?    @map(\"new_value\")\n  actorId       String?  @map(\"actor_id\") @db.Uuid\n  ipAddress     String?  @map(\"ip_address\") @db.VarChar(45)\n  // Standard tenant columns (createdBy = actorId by convention for audit logs)\n  createdAt     DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt     DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  createdBy     String   @map(\"created_by\") @db.Uuid\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n\n  @@index([tenantId])\n  @@index([entityType, entityId])\n  @@index([tenantId, entityType, entityId])\n  @@index([tenantId, createdAt])\n  @@map(\"driver_pay_audit_logs\")\n}\n\nmodel DocFeedback {\n  id        String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId  String   @db.Uuid\n  userId    String   @db.Uuid\n  docSlug   String\n  helpful   Boolean\n  comment   String?\n  createdAt DateTime @default(now()) @db.Timestamptz\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId])\n  @@index([docSlug])\n}\n\n// ==============================================\n// Notification System — Phase 41\n// ==============================================\n\nenum NotificationCategory {\n  USER\n  LOAD\n  DRIVER\n  TRUCK\n  MESSAGE\n  FINANCE\n  ROUTE\n  CUSTOMER\n  DIGEST\n}\n\nenum NotificationChannel {\n  EMAIL\n  IN_APP\n  // Added 20260802174618_add_push_notification_channel. Nothing sends on PUSH\n  // until Phase 10 wires the dispatcher — see DEC-2 in\n  // .planning/document-import/DECISIONS.md.\n  PUSH\n}\n\nenum NotificationSendStatus {\n  PENDING\n  SENT\n  FAILED\n  SKIPPED_DISABLED\n  SKIPPED_USER_PREF\n  SKIPPED_IDEMPOTENT\n}\n\n/// Global, system-level templates. No tenantId — owned by the platform.\nmodel NotificationTemplate {\n  id                 String               @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  triggerKey         String               @unique\n  category           NotificationCategory\n  displayName        String\n  description        String               @db.Text\n  defaultSubject     String\n  defaultBlockJson   Json\n  defaultHtmlCache   String?              @db.Text\n  availableVariables Json\n  defaultRecipients  Json\n  isActive           Boolean              @default(true)\n  inAppEnabled       Boolean              @default(true)\n  createdAt          DateTime             @default(now()) @db.Timestamptz\n  updatedAt          DateTime             @updatedAt @db.Timestamptz\n\n  @@index([category])\n  @@index([isActive])\n}\n\n/// Per-tenant overrides for each notification template. Auto-populated by trigger on Tenant insert.\nmodel TenantNotificationSettings {\n  id              String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId        String   @db.Uuid\n  triggerKey      String\n  isActive        Boolean  @default(true)\n  customSubject   String?\n  customBlockJson Json?\n  customHtmlCache String?  @db.Text\n  createdAt       DateTime @default(now()) @db.Timestamptz\n  updatedAt       DateTime @updatedAt @db.Timestamptz\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@unique([tenantId, triggerKey])\n  @@index([tenantId])\n  @@index([triggerKey])\n}\n\n/// Users who subscribe to specific notification triggers within a tenant.\nmodel NotificationSubscription {\n  id         String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId   String   @db.Uuid\n  triggerKey String\n  userId     String   @db.Uuid\n  createdAt  DateTime @default(now()) @db.Timestamptz\n  updatedAt  DateTime @updatedAt @db.Timestamptz\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([tenantId, triggerKey, userId])\n  @@index([tenantId])\n  @@index([userId])\n}\n\n/// Per-user channel preferences for each notification trigger.\nmodel UserNotificationPreference {\n  id           String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  userId       String    @db.Uuid\n  triggerKey   String\n  emailEnabled Boolean   @default(true)\n  inAppEnabled Boolean   @default(true)\n  createdAt    DateTime  @default(now()) @db.Timestamptz\n  updatedAt    DateTime  @updatedAt @db.Timestamptz\n  tenantId     String    @db.Uuid\n  createdBy    String?   @db.Uuid\n  updatedBy    String?   @db.Uuid\n  deletedAt    DateTime? @db.Timestamptz\n  deletedBy    String?   @db.Uuid\n\n  user    User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  tenant  Tenant @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n  creator User?  @relation(name: \"UserNotificationPreferenceCreatedBy\", fields: [createdBy], references: [id], onDelete: SetNull)\n\n  @@unique([userId, triggerKey])\n  @@index([userId])\n  @@index([tenantId])\n}\n\n/// Audit log of every notification send attempt. No RLS — system-level audit.\nmodel NotificationSendLog {\n  id                String                 @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId          String                 @db.Uuid\n  triggerKey        String\n  recipientUserId   String?                @db.Uuid\n  recipientEmail    String?\n  channel           NotificationChannel\n  subject           String?                @db.Text\n  status            NotificationSendStatus\n  errorMessage      String?                @db.Text\n  idempotencyKey    String\n  relatedEntityType String?\n  relatedEntityId   String?\n  sentAt            DateTime?              @db.Timestamptz\n  createdAt         DateTime               @default(now()) @db.Timestamptz\n  updatedAt         DateTime               @updatedAt @db.Timestamptz\n\n  @@index([tenantId])\n  @@index([triggerKey])\n  @@index([idempotencyKey])\n  @@index([status])\n  @@index([createdAt])\n}\n\n/// Single-row global email config. Enforced by a partial unique index in the migration.\nmodel NotificationEmailConfig {\n  id           String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  singletonKey String   @default(\"singleton\")\n  fromName     String\n  fromEmail    String\n  replyTo      String?\n  createdAt    DateTime @default(now()) @db.Timestamptz\n  updatedAt    DateTime @updatedAt @db.Timestamptz\n}\n\n/// Append-only audit log for PII access and restricted operations.\n/// Tenant-scoped, FORCE RLS, REVOKE UPDATE/DELETE from app_user.\n/// Part of DatabaseSecurity_MultiTenant_Spec_v1.md Section 4.4 (quick-329).\nmodel AuditLog {\n  id           String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tenantId     String   @map(\"tenant_id\") @db.Uuid\n  userId       String   @map(\"user_id\") @db.Uuid\n  action       String\n  resourceType String   @map(\"resource_type\")\n  resourceId   String   @map(\"resource_id\") @db.Uuid\n  fieldName    String?  @map(\"field_name\")\n  ipAddress    String?  @map(\"ip_address\")\n  userAgent    String?  @map(\"user_agent\")\n  createdAt    DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n  user   User   @relation(fields: [userId], references: [id])\n\n  @@index([tenantId, createdAt(sort: Desc)])\n  @@index([tenantId, userId, createdAt(sort: Desc)])\n  @@index([tenantId, resourceType, resourceId])\n  @@map(\"audit_log\")\n}\n\n/// User grid preferences for DataGrid columns, ordering, visibility, and density.\n/// Not tenant-scoped — preferences are personal per user across all tenants they belong to.\nmodel GridPreference {\n  id            String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  userId        String   @db.Uuid\n  gridId        String   @db.VarChar(100)\n  columnOrder   String[] @default([])\n  columnWidths  Json     @default(\"{}\")\n  hiddenColumns String[] @default([])\n  frozenColumns String[] @default([])\n  density       String   @default(\"normal\")\n  pageSize      Int      @default(25)\n  createdAt     DateTime @default(now()) @db.Timestamptz\n  updatedAt     DateTime @updatedAt @db.Timestamptz\n\n  @@unique([userId, gridId])\n  @@index([userId])\n  @@map(\"grid_preference\")\n}\n\n/// Saved grid views capturing complete grid state (filters, sort, columns, density).\n/// Personal to user — not tenant-scoped.\nmodel GridView {\n  id            String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  gridId        String   @db.VarChar(100)\n  userId        String   @db.Uuid\n  name          String   @db.VarChar(100)\n  isDefault     Boolean  @default(false)\n  schemaVersion Int      @default(1)\n  state         Json\n  createdAt     DateTime @default(now()) @db.Timestamptz\n  updatedAt     DateTime @updatedAt @db.Timestamptz\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([gridId, userId, name])\n  @@index([gridId, userId])\n  @@map(\"grid_view\")\n}\n"
